// ---- src/10-store.js ----

// Notebook files: data/assets/kmg-ink/<id>.json.
//
// v2: {v, paper, pages: [{id, w, h, bg, strokes, items}]}
//   stroke: {id, t: pen|ball|pencil|hl|shape, c, w, p: [[x, y, pressure]], sh?, sent?}
//   item:   {type: note|reply, text, y?, h?, mode?}   (notes carry the transcribed handwriting)
//   paper.reply: {font, line} fixes the reply text size (migrated notebooks); otherwise it follows the ruling.
// v1 (kmg11-12) was one growing sheet: {height, strokes, items, asked}.

const DEFAULT_PAPER = {pattern: "lined", line: 40, thick: 2, top: 2, color: "cream"};

const emptyPage = (w = PAGE_W, h = PAGE_H) => ({id: shortId(), w, h, bg: null, strokes: [], items: []});

const newNotebook = (paper = DEFAULT_PAPER) => ({v: 2, paper: {...DEFAULT_PAPER, ...paper}, pages: [emptyPage()]});

const pageIsEmpty = (page) => !page.bg && page.strokes.length === 0 && page.items.length === 0;

const pageContent = (file, text = "") => JSON.stringify({v: 1, file}) + (text ? "\n" + text : "");

const pageMarkdown = (file, text = "") => `;;;${INFO}\n${pageContent(file, text)}\n;;;`;

// Block content: the first line is JSON metadata, the rest is the conversation as plain text (so search finds it).
const parseContent = (content) => {
    const newline = content.indexOf("\n");
    const head = newline < 0 ? content : content.slice(0, newline);
    try {
        const meta = JSON.parse(head);
        return {meta, text: newline < 0 ? "" : content.slice(newline + 1)};
    } catch {
        return {meta: null, text: content};
    }
};

const conversationText = (data) => data.pages.flatMap(page => page.items).map(item =>
    item.type === "reply" ? `AI: ${item.text}` : `Me: ${item.text}`).join("\n")
    .split("\n").filter(line => line.trim() !== ";;;").join("\n");

// v1 page breaks: as low as possible within PAGE_H, but never through a stroke or a reply.
const pageBreaks = (spans, height) => {
    const breaks = [0];
    const bottom = Math.max(height, ...spans.map(span => span[1]));
    while (bottom - breaks[breaks.length - 1] > PAGE_H) {
        const top = breaks[breaks.length - 1];
        let cut = top + PAGE_H;
        for (let tries = 0; tries < 70; tries++) {
            const blocking = spans.filter(([a, b]) => a < cut && b > cut);
            if (blocking.length === 0) {
                break;
            }
            cut = Math.min(...blocking.map(([a]) => a)) - 10;
            if (cut <= top + PAGE_H / 2) {
                cut = top + PAGE_H; // nothing clean: cut anyway
                break;
            }
        }
        breaks.push(cut);
    }
    return breaks;
};

const migrateV1 = (old) => {
    const strokes = (old.strokes || []).filter(stroke => Array.isArray(stroke.p) && stroke.p.length);
    const replies = (old.items || []).filter(item => item.type === "reply");
    const spans = [
        ...strokes.map(stroke => [Math.min(...stroke.p.map(point => point[1])), Math.max(...stroke.p.map(point => point[1]))]),
        ...replies.map(item => [item.y || 0, (item.y || 0) + (item.h || 0)]),
    ];
    const breaks = pageBreaks(spans, old.height || PAGE_H);
    const pages = breaks.map(() => emptyPage());
    const pageAt = (y) => {
        let index = breaks.length - 1;
        while (index > 0 && breaks[index] > y) {
            index--;
        }
        return {page: pages[index], offset: breaks[index]};
    };
    (old.strokes || []).forEach((stroke, index) => {
        if (!Array.isArray(stroke.p) || stroke.p.length === 0) {
            return;
        }
        const {page, offset} = pageAt(Math.min(...stroke.p.map(point => point[1])));
        page.strokes.push({
            id: shortId(),
            t: "pen",
            c: stroke.c || "#1b1b1b",
            w: Math.round((stroke.w || 3) * 1.4 * 10) / 10,
            p: stroke.p.map(([x, y, pressure]) => [x, y - offset, pressure ?? 0.5]),
            sent: index < (old.asked || 0),
        });
    });
    // A transcript belongs with the reply that follows it.
    let notes = [];
    (old.items || []).forEach(item => {
        if (item.type !== "reply") {
            notes.push({type: "note", text: item.text});
            return;
        }
        const {page, offset} = pageAt(item.y || 0);
        page.items.push(...notes, {...item, y: (item.y || 0) - offset, h: item.h || 0});
        notes = [];
    });
    if (notes.length) {
        pages[pages.length - 1].items.push(...notes);
    }
    // v1 ruled a line every 50 units, starting 50 units down, and wrote replies at 34/44 units,
    // which its handwriting was placed around.
    return {v: 2, paper: {...DEFAULT_PAPER, line: 50, thick: 1.5, top: 1, reply: {font: 34, line: 44}}, pages};
};

const normalize = (data) => {
    if (!data || typeof data !== "object") {
        return null;
    }
    if (data.v !== 2) {
        return Array.isArray(data.strokes) ? migrateV1(data) : null;
    }
    if (!Array.isArray(data.pages)) {
        return null;
    }
    data.paper = {...DEFAULT_PAPER, ...(data.paper || {})};
    data.pages.forEach(page => {
        page.id = page.id || shortId();
        page.w = page.w || PAGE_W;
        page.h = page.h || PAGE_H;
        page.bg = page.bg || null;
        page.strokes = Array.isArray(page.strokes) ? page.strokes : [];
        page.items = Array.isArray(page.items) ? page.items : [];
        page.strokes.forEach(stroke => stroke.id = stroke.id || shortId());
    });
    if (data.pages.length === 0) {
        data.pages.push(emptyPage());
    }
    return data;
};

// Resolves to the notebook, or to null when the file is missing or unreadable.
// getFile answers errors with HTTP 202 and a JSON body.
const loadNotebook = async (file) => {
    const response = await fetch("/api/file/getFile", {method: "POST", body: JSON.stringify({path: `/data/${file}`})});
    if (response.status !== 200) {
        return null;
    }
    try {
        return normalize(await response.json());
    } catch (error) {
        console.warn(`${PLUGIN}: cannot read ${file}`, error);
        return null;
    }
};

const saveNotebook = async (file, data) => {
    const form = new FormData();
    form.append("path", `/data/${file}`);
    form.append("isDir", "false");
    form.append("modTime", String(Date.now())); // milliseconds, as putFile expects
    form.append("file", new Blob([JSON.stringify(data)], {type: "application/json"}), file.split("/").pop());
    const response = await fetch("/api/file/putFile", {method: "POST", body: form});
    const result = await response.json().catch(() => ({code: -1, msg: response.statusText}));
    if (result.code !== 0) {
        throw new Error(result.msg || "putFile failed");
    }
};

// One Doc per open file, shared by the note block and the full-screen tab.
class Doc extends EventTarget {
    constructor(file, data) {
        super();
        this.file = file;
        this.data = data;
        this.users = 0;
        this.saveTimer = 0;
        this.busy = false;
        this.history = new History(this);
    }

    // What changed: {pages: [page ids] | "all", paper?: true, structure?: true}
    changed(detail = {pages: "all"}, save = true) {
        this.dispatchEvent(new CustomEvent("change", {detail}));
        if (save) {
            this.scheduleSave();
        }
    }

    scheduleSave() {
        clearTimeout(this.saveTimer);
        this.saveTimer = setTimeout(() => this.save(), SAVE_DELAY);
    }

    save() {
        clearTimeout(this.saveTimer);
        this.saveTimer = 0;
        return saveNotebook(this.file, this.data).catch(error => {
            console.error(`${PLUGIN}: saving ${this.file} failed`, error);
            this.dispatchEvent(new CustomEvent("savefailed", {detail: error}));
        });
    }

    // Saber keeps one empty page at the end: writing on it adds the next.
    ensureTrailingPage() {
        const pages = this.data.pages;
        let changed = false;
        if (!pageIsEmpty(pages[pages.length - 1])) {
            pages.push(emptyPage());
            changed = true;
        }
        while (pages.length > 1 && pageIsEmpty(pages[pages.length - 1]) && pageIsEmpty(pages[pages.length - 2])) {
            pages.pop();
            changed = true;
        }
        return changed;
    }
}

const docs = new Map();

// A plugin reload runs this file again with a new docs map; the old copy's last saves finish first.
const FLUSH = "__kmgInkFlush";

const acquireDoc = async (file) => {
    await window[FLUSH];
    let entry = docs.get(file);
    if (!entry) {
        entry = {promise: loadNotebook(file).then(data => data && new Doc(file, data)), releaseTimer: 0};
        docs.set(file, entry);
    }
    clearTimeout(entry.releaseTimer);
    const doc = await entry.promise;
    if (!doc) {
        docs.delete(file);
        return null;
    }
    doc.users++;
    return doc;
};

// A released doc stays cached briefly: a block re-renders (and re-acquires) after every setContent.
const releaseDoc = (doc) => {
    doc.users--;
    if (doc.users > 0) {
        return null;
    }
    const saved = doc.saveTimer ? doc.save() : null;
    const entry = docs.get(doc.file);
    if (entry) {
        entry.releaseTimer = setTimeout(() => {
            if (doc.users <= 0) {
                docs.delete(doc.file);
            }
        }, 3000);
    }
    return saved;
};

// ---- src/15-history.js ----

// Undo and redo for one notebook. An operation is {apply(), revert(), detail}: apply has already
// run when it is pushed; detail is what doc.changed() reports after either direction.

class History {
    constructor(doc) {
        this.doc = doc;
        this.done = [];
        this.undone = [];
    }

    push(op) {
        this.done.push(op);
        if (this.done.length > 200) {
            this.done.shift();
        }
        this.undone = [];
        this.doc.changed(op.detail);
    }

    // Runs apply and records it.
    run(op) {
        op.apply();
        this.push(op);
    }

    undo() {
        const op = this.done.pop();
        if (!op) {
            return false;
        }
        op.revert();
        this.undone.push(op);
        this.doc.changed(op.detail);
        return true;
    }

    redo() {
        const op = this.undone.pop();
        if (!op) {
            return false;
        }
        op.apply();
        this.done.push(op);
        this.doc.changed(op.detail);
        return true;
    }
}

const opAddStroke = (page, stroke) => ({
    detail: {pages: [page.id]},
    apply: () => page.strokes.push(stroke),
    revert: () => {
        const index = page.strokes.indexOf(stroke);
        if (index >= 0) {
            page.strokes.splice(index, 1);
        }
    },
});

// removed: [{stroke, index}] in ascending index order, as they were before removal.
const opRemoveStrokes = (page, removed) => ({
    detail: {pages: [page.id]},
    apply: () => {
        const gone = new Set(removed.map(item => item.stroke));
        page.strokes = page.strokes.filter(stroke => !gone.has(stroke));
    },
    revert: () => removed.forEach(({stroke, index}) => page.strokes.splice(index, 0, stroke)),
});

// Replaces each stroke's points (and shape) by a transformed copy; before/after are [{stroke, p, sh}].
const opReshape = (page, before, after) => {
    const set = (states) => states.forEach(({stroke, p, sh}) => {
        stroke.p = p;
        if (sh) {
            stroke.sh = sh;
        }
        forgetOutline(stroke);
    });
    return {detail: {pages: [page.id]}, apply: () => set(after), revert: () => set(before)};
};

const opRecolor = (page, strokes, color) => {
    const old = strokes.map(stroke => stroke.c);
    return {
        detail: {pages: [page.id]},
        apply: () => strokes.forEach(stroke => {
            stroke.c = color;
        }),
        revert: () => strokes.forEach((stroke, index) => {
            stroke.c = old[index];
        }),
    };
};

const opPaper = (data, paper) => {
    const old = data.paper;
    return {
        detail: {pages: "all", paper: true},
        apply: () => {
            data.paper = paper;
        },
        revert: () => {
            data.paper = old;
        },
    };
};

// Any change to the page list: before/after are arrays of the same page objects.
const opPages = (data, before, after) => ({
    detail: {pages: "all", structure: true},
    apply: () => {
        data.pages = after.slice();
    },
    revert: () => {
        data.pages = before.slice();
    },
});

// ---- src/20-paper.js ----

// Paper: colour and ruling, per notebook. The patterns follow Saber's
// (packages/sbn/lib/canvas_background_pattern.dart and _canvas_background_painter.dart).

const PAPER_COLORS = {
    cream: {fill: "#fbf8f1", line: "rgba(80, 110, 160, .28)", margin: "rgba(200, 60, 60, .38)", dark: false},
    white: {fill: "#fcfcfc", line: "rgba(80, 110, 160, .26)", margin: "rgba(200, 60, 60, .36)", dark: false},
    dark: {fill: "#1e1f22", line: "rgba(150, 170, 210, .22)", margin: "rgba(230, 110, 110, .35)", dark: true},
};

const PATTERNS = ["blank", "lined", "college", "grid", "dots", "staffs", "tablature", "cornell"];

const paperColors = (paper) => PAPER_COLORS[paper.color] || PAPER_COLORS.cream;

// Draws the ruling of one page into ctx, which is already scaled to page units.
const drawPaper = (ctx, page, paper) => {
    const colors = paperColors(paper);
    const {w, h} = page;
    const line = paper.line;
    const top = (paper.top ?? 2) * line;
    ctx.fillStyle = colors.fill;
    ctx.fillRect(0, 0, w, h);
    if (page.bg) {
        return; // an imported page brings its own look
    }
    ctx.lineWidth = paper.thick;
    ctx.strokeStyle = colors.line;
    const hline = (y, x0 = 0, x1 = w) => {
        ctx.beginPath();
        ctx.moveTo(x0, y);
        ctx.lineTo(x1, y);
        ctx.stroke();
    };
    const vline = (x, y0 = 0, y1 = h) => {
        ctx.beginPath();
        ctx.moveTo(x, y0);
        ctx.lineTo(x, y1);
        ctx.stroke();
    };
    switch (paper.pattern) {
        case "lined":
            for (let y = top; y < h; y += line) {
                hline(y);
            }
            break;
        case "college":
            for (let y = top; y < h; y += line) {
                hline(y);
            }
            ctx.strokeStyle = colors.margin;
            vline(line * 2);
            break;
        case "grid":
            for (let y = line; y < h; y += line) {
                hline(y);
            }
            for (let x = line; x < w; x += line) {
                vline(x);
            }
            break;
        case "dots":
            ctx.fillStyle = colors.line;
            for (let y = line; y < h; y += line) {
                for (let x = line; x < w; x += line) {
                    ctx.beginPath();
                    ctx.arc(x, y, paper.thick * 4 / 3, 0, Math.PI * 2);
                    ctx.fill();
                }
            }
            break;
        case "staffs":
        case "tablature": {
            const lines = paper.pattern === "staffs" ? 5 : 6;
            const staff = (lines - 1) * line;
            for (let y = top; y + staff < h - line; y += staff + line * 3) {
                for (let i = 0; i < lines; i++) {
                    hline(y + i * line, line, w - line);
                }
            }
            break;
        }
        case "cornell": {
            const cue = w * 0.35;
            const summary = h * 0.7;
            hline(line * 2);
            hline(line * 3);
            for (let y = line * 5; y < summary; y += line) {
                hline(y);
            }
            ctx.strokeStyle = colors.margin;
            vline(cue, line * 3, summary);
            hline(summary);
            ctx.strokeStyle = colors.line;
            for (let y = summary + line * 2; y < h; y += line) {
                hline(y);
            }
            break;
        }
    }
};

// Where the next ruled line is at or below y, so replies sit on the lines.
const snapToLine = (paper, y) => {
    if (paper.pattern === "blank" || paper.pattern === "dots") {
        return y;
    }
    const top = (paper.top ?? 2) * paper.line;
    return top + Math.ceil((y - top) / paper.line) * paper.line;
};

// ---- src/30-strokes.js ----

// Stroke rendering. Strokes are filled outlines from perfect-freehand, in page units; the canvas
// context is scaled to the page. Settings per tool follow Saber (lib/data/tools/*.dart).

const TOOLS = {
    pen: {size: 5, sizes: [2, 3, 5, 8, 12], min: 1, max: 25},
    ball: {size: 5, sizes: [2, 3, 5, 8, 12], min: 1, max: 25},
    shape: {size: 5, sizes: [2, 3, 5, 8, 12], min: 1, max: 25},
    pencil: {size: 4, sizes: [2, 3, 4, 6, 9], min: 1, max: 15},
    hl: {size: 40, sizes: [20, 30, 40, 60, 80], min: 10, max: 100},
};

const INK_TOOLS = new Set(Object.keys(TOOLS));

const freehandOptions = (stroke) => {
    const simulatePressure = !stroke.pr;
    switch (stroke.t) {
        case "ball":
            return {size: stroke.w, thinning: 0, smoothing: 0.5, streamline: 0.5};
        case "pencil":
            return {
                size: stroke.w, thinning: 0.5, smoothing: 0.5, streamline: 0.1, simulatePressure,
                start: {taper: stroke.w * 4}, end: {taper: stroke.w * 4},
            };
        case "hl":
            return {size: stroke.w, thinning: 0, smoothing: 0.5, streamline: 0.5};
        default:
            return {size: stroke.w, thinning: 0.5, smoothing: 0.5, streamline: 0.5, simulatePressure};
    }
};

const outlines = new WeakMap();

const forgetOutline = (stroke) => outlines.delete(stroke);

const shapePath = (sh) => {
    const path = new Path2D();
    if (sh.k === "ellipse") {
        path.ellipse(sh.cx, sh.cy, Math.max(0.5, sh.rx), Math.max(0.5, sh.ry), sh.rot || 0, 0, Math.PI * 2);
        return path;
    }
    sh.pts.forEach(([x, y], index) => index ? path.lineTo(x, y) : path.moveTo(x, y));
    if (sh.k === "poly") {
        path.closePath();
    }
    return path;
};

// The outline as a smooth closed path (quadratic curves through the outline's midpoints).
const strokePath = (stroke) => {
    let path = outlines.get(stroke);
    if (path) {
        return path;
    }
    path = new Path2D();
    if (stroke.sh) {
        path = shapePath(stroke.sh);
    } else {
        const points = perfectFreehand.getStroke(stroke.p, {...freehandOptions(stroke), last: true});
        if (points.length) {
            path.moveTo(points[0][0], points[0][1]);
            for (let i = 0; i < points.length; i++) {
                const [x0, y0] = points[i];
                const [x1, y1] = points[(i + 1) % points.length];
                path.quadraticCurveTo(x0, y0, (x0 + x1) / 2, (y0 + y1) / 2);
            }
            path.closePath();
        }
    }
    outlines.set(stroke, path);
    return path;
};

const luminance = (hex) => {
    const value = parseInt(hex.slice(1, 7), 16);
    if (Number.isNaN(value)) {
        return 0.5;
    }
    const channel = (shift) => ((value >> shift) & 255) / 255;
    return 0.2126 * channel(16) + 0.7152 * channel(8) + 0.0722 * channel(0);
};

// On dark paper, dark ink shows light (Saber inverts the page instead; this keeps colours as chosen).
const inkColor = (color, paper) => paperColors(paper).dark && luminance(color) < 0.3 ? "#e6e6e6" : color;

const grains = new Map();

const grainPattern = (ctx, paper) => {
    const fill = paperColors(paper).fill;
    let tile = grains.get(fill);
    if (!tile) {
        tile = document.createElement("canvas");
        tile.width = tile.height = 64;
        const tileCtx = tile.getContext("2d");
        const image = tileCtx.createImageData(64, 64);
        const value = parseInt(fill.slice(1), 16);
        for (let i = 0; i < image.data.length; i += 4) {
            image.data[i] = (value >> 16) & 255;
            image.data[i + 1] = (value >> 8) & 255;
            image.data[i + 2] = value & 255;
            image.data[i + 3] = Math.random() < 0.35 ? Math.floor(Math.random() * 150) : 0;
        }
        tileCtx.putImageData(image, 0, 0);
        grains.set(fill, tile);
    }
    const pattern = ctx.createPattern(tile, "repeat");
    const scale = ctx.getTransform().a || 1;
    pattern.setTransform(new DOMMatrix().scale(1 / scale));
    return pattern;
};

// Draws one stroke; color overrides the stroke's colour (for AI images).
const drawStroke = (ctx, stroke, paper, color) => {
    const path = strokePath(stroke);
    const fill = color || inkColor(stroke.c, paper);
    if (stroke.sh) {
        ctx.save();
        ctx.strokeStyle = fill;
        ctx.lineWidth = stroke.w;
        ctx.lineCap = "round";
        ctx.lineJoin = "round";
        ctx.stroke(path);
        ctx.restore();
        return;
    }
    ctx.fillStyle = fill;
    ctx.fill(path);
    if (stroke.t === "pencil" && !color) {
        ctx.save();
        ctx.clip(path);
        ctx.fillStyle = grainPattern(ctx, paper);
        const b = strokeBounds([stroke]);
        ctx.fillRect(b.minX, b.minY, b.maxX - b.minX, b.maxY - b.minY);
        ctx.restore();
    }
};

// Highlighter strokes go on their own layer, drawn opaque; the layer's CSS opacity and blend mode
// keep overlaps from darkening and the ink above them readable.
const drawHighlights = (ctx, page, paper) => page.strokes.forEach(stroke => {
    if (stroke.t === "hl") {
        drawStroke(ctx, stroke, paper);
    }
});

const drawInk = (ctx, page, paper, skip) => page.strokes.forEach(stroke => {
    if (stroke.t !== "hl" && !skip?.has(stroke)) {
        drawStroke(ctx, stroke, paper);
    }
});

const strokeBounds = (strokes) => {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    strokes.forEach(stroke => {
        const pad = stroke.w / 2;
        stroke.p.forEach(([x, y]) => {
            minX = Math.min(minX, x - pad);
            minY = Math.min(minY, y - pad);
            maxX = Math.max(maxX, x + pad);
            maxY = Math.max(maxY, y + pad);
        });
    });
    return minX === Infinity ? null : {minX, minY, maxX, maxY};
};

const distanceToSegment = (x, y, [x0, y0], [x1, y1]) => {
    const dx = x1 - x0;
    const dy = y1 - y0;
    const length = dx * dx + dy * dy;
    const t = length ? clamp(((x - x0) * dx + (y - y0) * dy) / length, 0, 1) : 0;
    return Math.hypot(x - (x0 + t * dx), y - (y0 + t * dy));
};

const strokeHit = (stroke, x, y, radius) => {
    const reach = radius + stroke.w / 2;
    const p = stroke.p;
    if (p.length === 1) {
        return Math.hypot(x - p[0][0], y - p[0][1]) < reach;
    }
    for (let i = 1; i < p.length; i++) {
        if (distanceToSegment(x, y, p[i - 1], p[i]) < reach) {
            return true;
        }
    }
    return false;
};

const pointInPolygon = ([x, y], polygon) => {
    let inside = false;
    for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
        const [xi, yi] = polygon[i];
        const [xj, yj] = polygon[j];
        if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) {
            inside = !inside;
        }
    }
    return inside;
};

// A canvas with the given strokes, black on white, cropped; for the AI to read.
const renderStrokesImage = (strokes, paper) => {
    const ink = strokes.filter(stroke => stroke.t !== "hl");
    const bounds = strokeBounds(ink);
    if (!bounds) {
        return null;
    }
    const pad = 20;
    const width = bounds.maxX - bounds.minX + pad * 2;
    const height = bounds.maxY - bounds.minY + pad * 2;
    const scale = Math.min(AI_IMAGE_MAX / width, AI_IMAGE_MAX / height, 2);
    const canvas = document.createElement("canvas");
    canvas.width = Math.ceil(width * scale);
    canvas.height = Math.ceil(height * scale);
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.setTransform(scale, 0, 0, scale, (pad - bounds.minX) * scale, (pad - bounds.minY) * scale);
    ink.forEach(stroke => drawStroke(ctx, stroke, paper, "#000000"));
    return canvas;
};

// Stacks canvases vertically into one PNG data URL no larger than the AI image limit.
const stackImages = (canvases) => {
    const gap = 24;
    const width = Math.max(...canvases.map(item => item.width));
    const height = canvases.reduce((sum, item) => sum + item.height, 0) + gap * (canvases.length - 1);
    const scale = Math.min(1, AI_IMAGE_MAX / width, AI_IMAGE_MAX / height);
    const out = document.createElement("canvas");
    out.width = Math.ceil(width * scale);
    out.height = Math.ceil(height * scale);
    const ctx = out.getContext("2d");
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, out.width, out.height);
    let y = 0;
    canvases.forEach(item => {
        ctx.drawImage(item, 0, y * scale, item.width * scale, item.height * scale);
        y += item.height + gap;
    });
    return out.toDataURL("image/png");
};

// ---- src/40-shapes.js ----

// Shape recognition for the shape pen and for a pen held still at the end of a stroke:
// line, triangle, rectangle, star, ellipse (the shapes Saber's shape pen knows).

const dist = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1]);

const pathLength = (points) => {
    let length = 0;
    for (let i = 1; i < points.length; i++) {
        length += dist(points[i - 1], points[i]);
    }
    return length;
};

const simplifyOpen = (points, epsilon) => {
    if (points.length < 3) {
        return points.slice();
    }
    let farthest = 0;
    let index = 0;
    const first = points[0];
    const last = points[points.length - 1];
    for (let i = 1; i < points.length - 1; i++) {
        const d = distanceToSegment(points[i][0], points[i][1], first, last);
        if (d > farthest) {
            farthest = d;
            index = i;
        }
    }
    if (farthest <= epsilon) {
        return [first, last];
    }
    const left = simplifyOpen(points.slice(0, index + 1), epsilon);
    return left.slice(0, -1).concat(simplifyOpen(points.slice(index), epsilon));
};

// Corners of a closed path: split at the point farthest from the start, simplify both halves.
const simplifyClosed = (points, epsilon) => {
    let index = 0;
    let farthest = 0;
    points.forEach((point, i) => {
        const d = dist(points[0], point);
        if (d > farthest) {
            farthest = d;
            index = i;
        }
    });
    const a = simplifyOpen(points.slice(0, index + 1), epsilon);
    const b = simplifyOpen(points.slice(index).concat([points[0]]), epsilon);
    return a.slice(0, -1).concat(b.slice(0, -1));
};

const polygonArea = (points) => {
    let area = 0;
    for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
        area += (points[j][0] + points[i][0]) * (points[j][1] - points[i][1]);
    }
    return Math.abs(area / 2);
};

const cornerAngle = (a, b, c) => {
    const v1 = [a[0] - b[0], a[1] - b[1]];
    const v2 = [c[0] - b[0], c[1] - b[1]];
    const cos = (v1[0] * v2[0] + v1[1] * v2[1]) / (Math.hypot(...v1) * Math.hypot(...v2) || 1);
    return Math.acos(clamp(cos, -1, 1)) * 180 / Math.PI;
};

const snapLine = (a, b) => {
    const angle = Math.atan2(b[1] - a[1], b[0] - a[0]);
    const step = Math.PI / 4;
    const snapped = Math.round(angle / step) * step;
    if (Math.abs(angle - snapped) > 5 * Math.PI / 180) {
        return [a, b];
    }
    const length = dist(a, b);
    return [a, [a[0] + Math.cos(snapped) * length, a[1] + Math.sin(snapped) * length]];
};

const fitEllipse = (points) => {
    const n = points.length;
    const cx = points.reduce((sum, p) => sum + p[0], 0) / n;
    const cy = points.reduce((sum, p) => sum + p[1], 0) / n;
    let sxx = 0, syy = 0, sxy = 0;
    points.forEach(([x, y]) => {
        sxx += (x - cx) ** 2;
        syy += (y - cy) ** 2;
        sxy += (x - cx) * (y - cy);
    });
    let rot = 0.5 * Math.atan2(2 * sxy, sxx - syy);
    // Nearly axis-aligned ellipses snap straight.
    const step = Math.PI / 2;
    if (Math.abs(rot - Math.round(rot / step) * step) < 8 * Math.PI / 180) {
        rot = Math.round(rot / step) * step;
    }
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    let minU = Infinity, maxU = -Infinity, minV = Infinity, maxV = -Infinity;
    points.forEach(([x, y]) => {
        const u = (x - cx) * cos + (y - cy) * sin;
        const v = -(x - cx) * sin + (y - cy) * cos;
        minU = Math.min(minU, u);
        maxU = Math.max(maxU, u);
        minV = Math.min(minV, v);
        maxV = Math.max(maxV, v);
    });
    const du = (minU + maxU) / 2;
    const dv = (minV + maxV) / 2;
    return {
        k: "ellipse",
        cx: cx + du * cos - dv * sin,
        cy: cy + du * sin + dv * cos,
        rx: (maxU - minU) / 2,
        ry: (maxV - minV) / 2,
        rot,
    };
};

const regularStar = (points, corners) => {
    const cx = corners.reduce((sum, p) => sum + p[0], 0) / corners.length;
    const cy = corners.reduce((sum, p) => sum + p[1], 0) / corners.length;
    const radii = corners.map(p => dist(p, [cx, cy]));
    const outer = Math.max(...radii);
    const tip = corners[radii.indexOf(outer)];
    const start = Math.atan2(tip[1] - cy, tip[0] - cx);
    const inner = outer * 0.382;
    const pts = [];
    for (let i = 0; i < 10; i++) {
        const r = i % 2 ? inner : outer;
        const a = start + i * Math.PI / 5;
        pts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r]);
    }
    return {k: "poly", pts};
};

// Returns a shape ({k: line|poly|ellipse, ...}) or null. lenient: the pen was held on purpose.
const recognizeShape = (stroke, lenient = false) => {
    const points = stroke.map(([x, y]) => [x, y]);
    if (points.length < 3) {
        return null;
    }
    const length = pathLength(points);
    const xs = points.map(p => p[0]);
    const ys = points.map(p => p[1]);
    const w = Math.max(...xs) - Math.min(...xs);
    const h = Math.max(...ys) - Math.min(...ys);
    if (Math.max(w, h) < 12) {
        return null;
    }
    const first = points[0];
    const last = points[points.length - 1];
    if (dist(first, last) / length >= (lenient ? 0.85 : 0.93)) {
        return {k: "line", pts: snapLine(first, last)};
    }
    if (dist(first, last) > 0.3 * Math.max(w, h)) {
        return null; // not closed
    }
    const corners = simplifyClosed(points, 0.035 * length);
    const circularity = 4 * Math.PI * polygonArea(points) / (length * length);
    const n = corners.length;
    if (n === 3) {
        return {k: "poly", pts: corners};
    }
    if (n === 4) {
        const right = corners.every((corner, i) =>
            Math.abs(cornerAngle(corners[(i + 3) % 4], corner, corners[(i + 1) % 4]) - 90) < 22);
        if (right) {
            const edge = Math.atan2(corners[1][1] - corners[0][1], corners[1][0] - corners[0][0]);
            const off = Math.abs(edge - Math.round(edge / (Math.PI / 2)) * (Math.PI / 2));
            if (off < 12 * Math.PI / 180) {
                const x0 = Math.min(...corners.map(p => p[0]));
                const x1 = Math.max(...corners.map(p => p[0]));
                const y0 = Math.min(...corners.map(p => p[1]));
                const y1 = Math.max(...corners.map(p => p[1]));
                return {k: "poly", pts: [[x0, y0], [x1, y0], [x1, y1], [x0, y1]]};
            }
            return {k: "poly", pts: corners};
        }
    }
    if (n >= 9 && n <= 11 && circularity < 0.6) {
        return regularStar(points, corners);
    }
    if (n >= 4 && circularity > 0.68) {
        return fitEllipse(points);
    }
    return null;
};

// Points along a shape, so bounds, erasing and the lasso treat it like any stroke.
const shapePoints = (sh) => {
    const out = [];
    if (sh.k === "ellipse") {
        for (let i = 0; i <= 64; i++) {
            const a = i / 64 * Math.PI * 2;
            const u = Math.cos(a) * sh.rx;
            const v = Math.sin(a) * sh.ry;
            const cos = Math.cos(sh.rot || 0);
            const sin = Math.sin(sh.rot || 0);
            out.push([sh.cx + u * cos - v * sin, sh.cy + u * sin + v * cos, 0.5]);
        }
        return out;
    }
    const pts = sh.k === "poly" ? sh.pts.concat([sh.pts[0]]) : sh.pts;
    for (let i = 1; i < pts.length; i++) {
        const steps = Math.max(1, Math.ceil(dist(pts[i - 1], pts[i]) / 6));
        for (let s = i === 1 ? 0 : 1; s <= steps; s++) {
            const t = s / steps;
            out.push([pts[i - 1][0] + (pts[i][0] - pts[i - 1][0]) * t, pts[i - 1][1] + (pts[i][1] - pts[i - 1][1]) * t, 0.5]);
        }
    }
    return out;
};

// Applies an affine map (x, y) => [x', y'] to a shape; ellipses are only translated and scaled.
const mapShape = (sh, map, scale = 1) => {
    if (!sh) {
        return sh;
    }
    if (sh.k === "ellipse") {
        const [cx, cy] = map(sh.cx, sh.cy);
        return {...sh, cx, cy, rx: sh.rx * scale, ry: sh.ry * scale};
    }
    return {...sh, pts: sh.pts.map(([x, y]) => map(x, y))};
};

// ---- src/50-ui.js ----

// Small UI helpers: icons, popovers, the note text sent to the AI as context.

const svgIcon = (body) => `<svg class="kmg-ink__icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${body}</svg>`;

const ICONS = {
    pen: svgIcon(`<path d="M4 20l1.2-4.6L15.8 4.8a2 2 0 0 1 2.8 0l.6.6a2 2 0 0 1 0 2.8L8.6 18.8z"/><path d="M13.5 7l3.5 3.5"/>`),
    ball: svgIcon(`<path d="M5 19l1.5-4.5 9.8-9.8 3 3-9.8 9.8z"/><circle cx="5" cy="19" r="1.2" fill="currentColor"/>`),
    shape: svgIcon(`<rect x="3" y="12" width="8" height="8" rx="1"/><circle cx="16.5" cy="7.5" r="4.5"/>`),
    pencil: svgIcon(`<path d="M4 20l1-4.5L15.5 5l3.5 3.5L8.5 19z"/><path d="M5 15.5L8.5 19"/><path d="M13.5 7l3.5 3.5"/>`),
    hl: svgIcon(`<path d="M9 17l-3-3 9-9 3 3z"/><path d="M6 14l-2 4h5l0-1"/><path d="M4 21h16" stroke-width="3" opacity=".45"/>`),
    eraser: svgIcon(`<path d="M8.5 19.5L3.8 14.8a1.5 1.5 0 0 1 0-2.1l8.9-8.9a1.5 1.5 0 0 1 2.1 0l5.3 5.3a1.5 1.5 0 0 1 0 2.1l-8.2 8.3z"/><path d="M8 10l6 6"/><path d="M12 20h8"/>`),
    lasso: svgIcon(`<ellipse cx="12" cy="9" rx="8" ry="5" stroke-dasharray="3 2.2"/><path d="M7.5 13c-.8 2.2.3 4.8 2.8 6"/>`),
    undo: svgIcon(`<path d="M9 14L4 9l5-5"/><path d="M4 9h10.5a5.5 5.5 0 0 1 0 11H11"/>`),
    redo: svgIcon(`<path d="M15 14l5-5-5-5"/><path d="M20 9H9.5a5.5 5.5 0 0 0 0 11H13"/>`),
    finger: svgIcon(`<path d="M9 12V5.5a1.5 1.5 0 0 1 3 0V11"/><path d="M12 10.5a1.5 1.5 0 0 1 3 0V12"/><path d="M15 11.5a1.5 1.5 0 0 1 3 0V15a6 6 0 0 1-6 6h-.6a6 6 0 0 1-4.6-2.2L4.5 16a1.5 1.5 0 0 1 2.3-1.9L9 16"/>`),
    paper: svgIcon(`<rect x="5" y="3" width="14" height="18" rx="1.5"/><path d="M8 8h8M8 12h8M8 16h5"/>`),
    pages: svgIcon(`<rect x="8" y="3" width="12" height="15" rx="1.5"/><path d="M5 7v12.5A1.5 1.5 0 0 0 6.5 21H16"/>`),
    fullscreen: svgIcon(`<path d="M4 9V4h5M15 4h5v5M20 15v5h-5M9 20H4v-5"/>`),
    size: svgIcon(`<path d="M4 7h16" stroke-width="1.2"/><path d="M4 12h16" stroke-width="2.4"/><path d="M4 17.5h16" stroke-width="4"/>`),
    up: svgIcon(`<path d="M6 14l6-6 6 6"/>`),
    down: svgIcon(`<path d="M6 10l6 6 6-6"/>`),
    copy: svgIcon(`<rect x="8" y="8" width="12" height="12" rx="1.5"/><path d="M16 8V5.5A1.5 1.5 0 0 0 14.5 4h-9A1.5 1.5 0 0 0 4 5.5v9A1.5 1.5 0 0 0 5.5 16H8"/>`),
    add: svgIcon(`<path d="M12 5v14M5 12h14"/>`),
    clear: svgIcon(`<path d="M5 5l14 14M19 5L5 19"/>`),
    trash: svgIcon(`<path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3"/>`),
    sparkle: svgIcon(`<path d="M12 3l1.8 4.9L19 9.7l-5.2 1.8L12 16.5l-1.8-5L5 9.7l5.2-1.8z"/><path d="M18.5 15.5l.8 2 2 .8-2 .8-.8 2-.8-2-2-.8 2-.8z"/>`),
    pdf: svgIcon(`<path d="M14 3H7a1.5 1.5 0 0 0-1.5 1.5v15A1.5 1.5 0 0 0 7 21h10a1.5 1.5 0 0 0 1.5-1.5V7.5z"/><path d="M14 3v4.5h4.5"/><path d="M9 13h6M9 16.5h4"/>`),
};

let openPopoverElement = null;

const closePopover = () => {
    if (openPopoverElement) {
        openPopoverElement.dispatchEvent(new CustomEvent("close"));
        openPopoverElement.remove();
        openPopoverElement = null;
    }
};

// A floating panel under (or above) anchor; closes on a press outside it or Escape.
const openPopover = (anchor, html, className = "") => {
    closePopover();
    const popover = document.createElement("div");
    popover.className = `kmg-ink-popover ${className}`;
    popover.innerHTML = html;
    document.body.append(popover);
    const rect = anchor.getBoundingClientRect();
    const width = popover.offsetWidth;
    const height = popover.offsetHeight;
    const left = clamp(rect.left, 8, window.innerWidth - width - 8);
    const below = rect.bottom + 6;
    const top = below + height > window.innerHeight - 8 ? Math.max(8, rect.top - height - 6) : below;
    popover.style.left = `${left}px`;
    popover.style.top = `${top}px`;
    const onDown = (event) => {
        if (!popover.contains(event.target) && !anchor.contains(event.target)) {
            closePopover();
        }
    };
    const onKey = (event) => {
        if (event.key === "Escape") {
            closePopover();
        }
    };
    document.addEventListener("pointerdown", onDown, true);
    document.addEventListener("keydown", onKey, true);
    popover.addEventListener("close", () => {
        document.removeEventListener("pointerdown", onDown, true);
        document.removeEventListener("keydown", onKey, true);
    });
    openPopoverElement = popover;
    return popover;
};

// The note around a handwriting block, as plain text.
const documentContext = (blockElement) => {
    const wysiwyg = blockElement?.closest(".protyle-wysiwyg");
    if (!wysiwyg) {
        return "";
    }
    const parts = [];
    wysiwyg.querySelectorAll(":scope > [data-node-id]").forEach(item => {
        if (item === blockElement) {
            parts.push("[this handwriting notebook]");
        } else if (item.getAttribute("data-type") === "NodeCustomBlock" && item.getAttribute("data-info") === INFO) {
            parts.push(parseContent(item.getAttribute("data-content") || "").text);
        } else {
            parts.push(item.textContent || "");
        }
    });
    const text = parts.join("\n").trim();
    return text.length > MAX_CONTEXT ? text.slice(-MAX_CONTEXT) : text;
};

// The same for a block that is not on screen (the full-screen tab): the note exported as Markdown.
const documentContextById = async (blockId) => {
    if (!blockId) {
        return "";
    }
    const info = await fetchSyncPost("/api/block/getBlockInfo", {id: blockId});
    if (info.code !== 0 || !info.data?.rootID) {
        return "";
    }
    const exported = await fetchSyncPost("/api/export/exportMdContent", {id: info.data.rootID});
    const text = (exported.data?.content || "")
        .split("\n")
        .filter(line => !line.startsWith(`;;;${INFO}`) && !line.startsWith("{\"v\":1,\"file\"") && line.trim() !== ";;;")
        .join("\n").trim();
    return text.length > MAX_CONTEXT ? text.slice(-MAX_CONTEXT) : text;
};

const askAI = (body) => fetchSyncPost("/api/ai/ink/reply", body).then(response => {
    if (response.code !== 0) {
        throw new Error(response.msg || "the AI did not answer");
    }
    return response.data;
});

// ---- src/60-notebook.js ----

// The notebook view: a column of pages with a toolbar. It runs inside the note block
// (mode "block") and in the full-screen tab (mode "tab"); both edit the same Doc.

const PEN_KINDS = ["pen", "ball", "shape"];

class NotebookView {
    constructor({plugin, element, file, mode, blockId, blockElement, setContent}) {
        this.plugin = plugin;
        this.i18n = plugin.i18n;
        this.host = element;
        this.file = file;
        this.mode = mode;
        this.blockId = blockId || "";
        this.blockElement = blockElement || null;
        this.setContent = setContent || null;
        this.views = new Map(); // page id -> page view
        this.zoom = 1;
        this.current = null;
        this.touches = new Map();
        this.gesture = null;
        this.selection = null;
        this.disposed = false;
        this.frame = 0;
        this.dirtyViews = new Set();
    }

    get settings() {
        return this.plugin.settings;
    }

    get tool() {
        return this.settings.tool || "pen";
    }

    // Colour and width belong to the tool, as in Saber.
    toolState(tool = this.tool) {
        const key = INK_TOOLS.has(tool) ? tool : this.settings.penKind || "pen";
        const tools = this.settings.tools;
        if (!tools[key]) {
            tools[key] = {c: key === "hl" ? "#fdff6b" : key === "pencil" ? "#424242" : "#1b1b1b", w: TOOLS[key].size};
        }
        return tools[key];
    }

    async start() {
        this.host.innerHTML = `<div class="kmg-ink__status kmg-ink__status--center">${this.i18n.loading}</div>`;
        await this.plugin.settingsReady;
        const doc = await acquireDoc(this.file);
        if (this.disposed) {
            if (doc) {
                releaseDoc(doc);
            }
            return;
        }
        if (!doc) {
            this.host.innerHTML = `<div class="kmg-ink__error">${this.i18n.brokenPage}</div>`;
            return;
        }
        this.doc = doc;
        this.plugin.views.add(this);
        if (this.blockId) {
            doc.blockId = this.blockId;
        }
        if (doc.ensureTrailingPage()) {
            doc.changed({pages: "all", structure: true});
        }
        this.build();
        this.onChange = (event) => this.applyChange(event.detail);
        this.onStatus = () => this.updateStatus();
        this.onSaveFailed = () => this.setStatus(this.i18n.saveFailed);
        doc.addEventListener("change", this.onChange);
        doc.addEventListener("status", this.onStatus);
        doc.addEventListener("savefailed", this.onSaveFailed);
        if (this.setContent) {
            this.writeConversation = () => this.setContent(pageContent(this.file, conversationText(doc.data)));
            doc.blockWriters = doc.blockWriters || new Set();
            doc.blockWriters.add(this.writeConversation);
        }
        this.syncPages();
        this.updateStatus();
        this.updateHistoryButtons();
    }

    dispose() {
        if (this.disposed) {
            return null;
        }
        this.disposed = true;
        this.plugin.views.delete(this);
        closePopover();
        cancelAnimationFrame(this.frame);
        this.observer?.disconnect();
        this.resizeObserver?.disconnect();
        if (this.doc) {
            this.doc.removeEventListener("change", this.onChange);
            this.doc.removeEventListener("status", this.onStatus);
            this.doc.removeEventListener("savefailed", this.onSaveFailed);
            this.doc.blockWriters?.delete(this.writeConversation);
            return releaseDoc(this.doc);
        }
        return null;
    }

    // ---- DOM ----

    build() {
        const i18n = this.i18n;
        const button = (attrs, icon, title, extra = "") =>
            `<button class="kmg-ink__tool ${extra}" ${attrs} title="${escapeHtml(title)}">${icon}</button>`;
        const fullscreen = this.mode === "block" && !isMobile() ?
            button(`data-action="fullscreen"`, ICONS.fullscreen, i18n.fullscreen) : "";
        this.host.innerHTML = `<div class="kmg-ink kmg-ink--${this.mode}" tabindex="0">
    <div class="kmg-ink__toolbar">
        <div class="kmg-ink__group">
            ${button(`data-tool="pen"`, ICONS[this.settings.penKind || "pen"], i18n.penTip)}
            ${button(`data-tool="pencil"`, ICONS.pencil, i18n.pencil)}
            ${button(`data-tool="hl"`, ICONS.hl, i18n.highlighter)}
            ${button(`data-tool="eraser"`, ICONS.eraser, i18n.eraser)}
            ${button(`data-tool="lasso"`, ICONS.lasso, i18n.lasso)}
        </div>
        <div class="kmg-ink__group">
            <button class="kmg-ink__swatch kmg-ink__swatch--current" data-action="colors" title="${i18n.color}"></button>
            <span class="kmg-ink__recent"></span>
            ${button(`data-action="size"`, ICONS.size, i18n.size)}
        </div>
        <div class="kmg-ink__group">
            ${button(`data-action="undo"`, ICONS.undo, i18n.undo)}
            ${button(`data-action="redo"`, ICONS.redo, i18n.redo)}
            ${button(`data-action="finger"`, ICONS.finger, i18n.fingerDrawing)}
        </div>
        <span class="kmg-ink__spacer"></span>
        <span class="kmg-ink__status"></span>
        <div class="kmg-ink__group">
            ${button(`data-action="paper"`, ICONS.paper, i18n.paper)}
            ${button(`data-action="pages"`, ICONS.pages, i18n.pages)}
            ${fullscreen}
        </div>
        <div class="kmg-ink__group">
            <button class="kmg-ink__text" data-action="quiz" title="${escapeHtml(i18n.quizTip)}">${i18n.quiz}</button>
            <button class="kmg-ink__ask" data-action="ask" title="${escapeHtml(i18n.askTip)}">${i18n.ask}</button>
        </div>
    </div>
    <div class="kmg-ink__scroller"><div class="kmg-ink__pages"></div></div>
</div>`;
        this.root = this.host.querySelector(".kmg-ink");
        this.toolbar = this.root.querySelector(".kmg-ink__toolbar");
        this.scrollEl = this.root.querySelector(".kmg-ink__scroller");
        this.pagesEl = this.root.querySelector(".kmg-ink__pages");
        this.statusEl = this.root.querySelector(".kmg-ink__status");
        this.live = document.createElement("canvas");
        this.live.className = "kmg-ink__live";

        this.toolbar.addEventListener("click", (event) => this.onToolbarClick(event));
        this.pagesEl.addEventListener("pointerdown", (event) => this.onPointerDown(event));
        this.pagesEl.addEventListener("pointermove", (event) => this.onPointerMove(event));
        this.pagesEl.addEventListener("pointerup", (event) => this.onPointerUp(event));
        this.pagesEl.addEventListener("pointercancel", (event) => this.onPointerUp(event, true));
        this.pagesEl.addEventListener("contextmenu", (event) => event.preventDefault());
        this.pagesEl.addEventListener("click", (event) => this.onPagesClick(event));
        this.root.addEventListener("keydown", (event) => this.onKeyDown(event));
        if (this.mode === "tab") {
            this.scrollEl.addEventListener("wheel", (event) => this.onWheel(event), {passive: false});
        }

        const scrollRoot = this.mode === "tab" ? this.scrollEl : null;
        this.observer = new IntersectionObserver((entries) => entries.forEach(entry => {
            const view = this.views.get(entry.target.dataset.page);
            if (!view) {
                return;
            }
            view.visible = entry.isIntersecting;
            if (view.visible) {
                this.renderView(view);
            } else {
                this.freeView(view);
            }
        }), {root: scrollRoot, rootMargin: "600px 0px"});
        this.resizeObserver = new ResizeObserver(() => this.layout());
        this.resizeObserver.observe(this.root);
        this.refreshToolbar();
    }

    layout() {
        if (this.mode === "tab") {
            const base = Math.min(this.scrollEl.clientWidth - 32, 1000);
            this.pagesEl.style.width = `${Math.max(200, base * this.zoom)}px`;
        }
        this.views.forEach(view => view.visible && this.markDirty(view));
    }

    syncPages() {
        const pages = this.doc.data.pages;
        const keep = new Set(pages.map(page => page.id));
        this.views.forEach((view, id) => {
            if (!keep.has(id)) {
                this.observer.unobserve(view.el);
                view.el.remove();
                this.views.delete(id);
            }
        });
        pages.forEach((page, index) => {
            let view = this.views.get(page.id);
            if (!view) {
                view = this.createView(page);
                this.views.set(page.id, view);
                this.observer.observe(view.el);
            }
            view.page = page;
            view.el.style.aspectRatio = `${page.w} / ${page.h}`;
            view.number.textContent = `${index + 1} / ${pages.length}`;
            if (this.pagesEl.children[index] !== view.el) {
                this.pagesEl.insertBefore(view.el, this.pagesEl.children[index] || null);
            }
        });
        if (this.selection && !keep.has(this.selection.page.id)) {
            this.clearSelection();
        }
        this.layout();
    }

    createView(page) {
        const el = document.createElement("div");
        el.className = "kmg-ink__page";
        el.dataset.page = page.id;
        el.innerHTML = `<canvas class="kmg-ink__bg"></canvas><canvas class="kmg-ink__hl"></canvas><canvas class="kmg-ink__ink"></canvas>
<div class="kmg-ink__replies"></div><div class="kmg-ink__number"></div>`;
        return {
            page,
            el,
            bg: el.querySelector(".kmg-ink__bg"),
            hl: el.querySelector(".kmg-ink__hl"),
            ink: el.querySelector(".kmg-ink__ink"),
            replies: el.querySelector(".kmg-ink__replies"),
            number: el.querySelector(".kmg-ink__number"),
            visible: false,
            size: "",
            repliesKey: "",
        };
    }

    freeView(view) {
        [view.bg, view.hl, view.ink].forEach(canvas => {
            canvas.width = 0;
            canvas.height = 0;
        });
        view.size = "";
    }

    markDirty(view) {
        this.dirtyViews.add(view);
        if (!this.frame) {
            this.frame = requestAnimationFrame(() => {
                this.frame = 0;
                const views = [...this.dirtyViews];
                this.dirtyViews.clear();
                views.forEach(item => item.visible && this.renderView(item));
                if (this.current?.kind === "ink" || this.current?.kind === "lasso") {
                    this.drawLive();
                }
            });
        }
    }

    // Canvas backing size: device pixels, capped so a zoomed page stays within 12 megapixels.
    canvasMetrics(view) {
        const cssW = view.el.clientWidth;
        const page = view.page;
        const s = cssW / page.w;
        const cssH = page.h * s;
        const ratio = Math.min(window.devicePixelRatio || 1, Math.sqrt(12e6 / Math.max(1, cssW * cssH)));
        return {s, ratio, width: Math.round(cssW * ratio), height: Math.round(cssH * ratio)};
    }

    renderView(view) {
        if (this.disposed || !view.el.isConnected) {
            return;
        }
        const {s, ratio, width, height} = this.canvasMetrics(view);
        if (!width) {
            return;
        }
        const paper = this.doc.data.paper;
        const size = `${width}x${height}`;
        const resized = view.size !== size;
        [view.bg, view.hl, view.ink].forEach(canvas => {
            if (resized) {
                canvas.width = width;
                canvas.height = height;
            }
        });
        view.size = size;
        const context = (canvas) => {
            const ctx = canvas.getContext("2d");
            ctx.setTransform(1, 0, 0, 1, 0, 0);
            ctx.clearRect(0, 0, width, height);
            ctx.setTransform(ratio * s, 0, 0, ratio * s, 0, 0);
            return ctx;
        };
        drawPaper(context(view.bg), view.page, paper);
        this.drawBackground?.(view, context(view.bg), s, ratio);
        drawHighlights(context(view.hl), view.page, paper);
        drawInk(context(view.ink), view.page, paper);
        view.el.classList.toggle("kmg-ink__page--dark", paperColors(paper).dark);
        this.renderReplies(view, s);
        this.renderSelection(view, s);
    }

    renderReplies(view, s) {
        const page = view.page;
        const paper = this.doc.data.paper;
        const line = paper.reply?.line || (paper.pattern === "blank" || paper.pattern === "dots" ? 44 : paper.line);
        // Measuring a reply sets its h; that alone does not rebuild the replies.
        const key = JSON.stringify([page.items.map(item => [item.type, item.text, item.y]), line, paper.color]);
        const box = view.replies;
        box.style.width = `${page.w}px`;
        box.style.height = `${page.h}px`;
        box.style.transform = `scale(${s})`;
        if (key === view.repliesKey) {
            return;
        }
        view.repliesKey = key;
        box.style.lineHeight = `${line}px`;
        box.style.fontSize = `${paper.reply?.font || Math.round(clamp(line * 0.78, 24, 60))}px`;
        box.style.color = paperColors(paper).dark ? REPLY_COLOR_DARK : REPLY_COLOR;
        const fresh = view.freshReply;
        view.freshReply = null;
        box.innerHTML = "";
        page.items.forEach((item, index) => {
            if (item.type !== "reply") {
                return;
            }
            const reply = document.createElement("div");
            reply.className = "kmg-ink__reply";
            reply.dataset.index = String(index);
            reply.style.top = `${item.y}px`;
            reply.style.left = `${REPLY_LEFT}px`;
            reply.style.width = `${REPLY_WIDTH}px`;
            reply.textContent = item.text;
            if (item === fresh) {
                reply.classList.add("kmg-ink__reply--new");
            }
            box.append(reply);
        });
        this.measureReplies(view);
    }

    // A reply's height is measured once, after the handwriting font has loaded. One that runs off
    // the page moves to the top of the next page.
    async measureReplies(view) {
        const page = view.page;
        if (!page.items.some(item => item.type === "reply" && !item.h)) {
            return;
        }
        await document.fonts.load(`40px "KMG Ink Hand"`).catch(() => null);
        if (this.disposed || !view.el.isConnected) {
            return;
        }
        let changed = false;
        view.replies.querySelectorAll(".kmg-ink__reply").forEach(element => {
            const item = page.items[Number(element.dataset.index)];
            if (!item || item.h || !element.offsetHeight) {
                return;
            }
            item.h = element.offsetHeight + 10;
            changed = true;
            if (item.y + item.h > page.h - 20 && item.y > this.firstLineTop()) {
                this.moveReplyToNextPage(page, item);
            }
        });
        if (changed) {
            this.doc.ensureTrailingPage();
            this.doc.changed({pages: "all", structure: true});
        }
    }

    firstLineTop() {
        const paper = this.doc.data.paper;
        return this.replyTop(snapToLine(paper, (paper.top ?? 2) * paper.line), 0);
    }

    moveReplyToNextPage(page, item) {
        const pages = this.doc.data.pages;
        const index = pages.indexOf(page);
        let next = pages[index + 1];
        if (!next || next.bg || next.strokes.some(stroke => strokeBounds([stroke]).minY < item.h + 80)) {
            next = emptyPage(page.w, page.h);
            pages.splice(index + 1, 0, next);
        }
        const at = page.items.indexOf(item);
        // The transcript before the reply moves with it.
        const start = at > 0 && page.items[at - 1].type === "note" ? at - 1 : at;
        const moved = page.items.splice(start, at - start + 1);
        const top = this.firstLineTop();
        moved.forEach(entry => {
            if (entry.type === "reply") {
                entry.y = top;
            }
        });
        next.items.push(...moved);
    }

    // The top of a reply box whose first line of text sits on the ruled line at lineY.
    replyTop(lineY, bottom) {
        const paper = this.doc.data.paper;
        if (paper.pattern === "blank" || paper.pattern === "dots") {
            return Math.round(bottom + 24);
        }
        return Math.round(lineY - paper.line * 0.88);
    }

    renderSelection(view, s) {
        view.el.querySelector(".kmg-ink__sel")?.remove();
        view.el.querySelector(".kmg-ink__selbar")?.remove();
        const selection = this.selection;
        if (!selection || selection.page !== view.page) {
            return;
        }
        const b = strokeBounds([...selection.strokes]);
        if (!b) {
            return;
        }
        selection.bounds = b;
        const box = document.createElement("div");
        box.className = "kmg-ink__sel";
        box.style.left = `${b.minX * s - 4}px`;
        box.style.top = `${b.minY * s - 4}px`;
        box.style.width = `${(b.maxX - b.minX) * s + 8}px`;
        box.style.height = `${(b.maxY - b.minY) * s + 8}px`;
        box.innerHTML = `<div class="kmg-ink__handle"></div>`;
        view.el.append(box);
        if (this.current?.kind === "move" || this.current?.kind === "scale") {
            return;
        }
        const bar = document.createElement("div");
        bar.className = "kmg-ink__selbar";
        bar.innerHTML = `<button data-sel="duplicate" title="${this.i18n.duplicate}">${ICONS.copy}</button>
<button data-sel="delete" title="${this.i18n.delete}">${ICONS.trash}</button>
${this.plugin.explainSelection ? `<button data-sel="explain" title="${this.i18n.explainTip}">${ICONS.sparkle}<span>${this.i18n.explain}</span></button>` : ""}`;
        bar.style.left = `${Math.max(0, b.minX * s - 4)}px`;
        const above = b.minY * s - 46;
        bar.style.top = `${above > 0 ? above : (b.maxY * s + 10)}px`;
        view.el.append(bar);
    }

    // ---- status and toolbar ----

    setStatus(text) {
        if (this.statusEl) {
            this.statusEl.textContent = text;
        }
    }

    updateStatus() {
        this.root?.classList.toggle("kmg-ink--busy", !!this.doc.busy);
        this.setStatus(this.doc.busy ? this.i18n.thinking : "");
    }

    updateHistoryButtons() {
        if (!this.toolbar) {
            return;
        }
        this.toolbar.querySelector('[data-action="undo"]').disabled = this.doc.history.done.length === 0;
        this.toolbar.querySelector('[data-action="redo"]').disabled = this.doc.history.undone.length === 0;
    }

    refreshToolbar() {
        const tool = this.tool;
        const penKind = this.settings.penKind || "pen";
        this.toolbar.querySelectorAll("[data-tool]").forEach(item => {
            const on = item.dataset.tool === tool || (item.dataset.tool === "pen" && PEN_KINDS.includes(tool));
            item.classList.toggle("kmg-ink__tool--on", on);
        });
        this.toolbar.querySelector('[data-tool="pen"]').innerHTML = ICONS[penKind];
        const state = this.toolState();
        const current = this.toolbar.querySelector(".kmg-ink__swatch--current");
        current.style.background = state.c;
        this.toolbar.querySelector(".kmg-ink__recent").innerHTML = this.settings.recent.slice(0, 3).map(color =>
            `<button class="kmg-ink__swatch" data-color="${color}" style="background:${color}" title="${color}"></button>`).join("");
        this.toolbar.querySelector('[data-action="finger"]').classList.toggle("kmg-ink__tool--on", this.settings.fingerDraw !== false);
        this.root.classList.toggle("kmg-ink--lasso", tool === "lasso");
        this.root.classList.toggle("kmg-ink--eraser", tool === "eraser");
    }

    setTool(tool) {
        if (PEN_KINDS.includes(tool)) {
            this.settings.penKind = tool;
        }
        if (tool !== "lasso") {
            this.clearSelection();
        }
        this.settings.tool = tool;
        this.plugin.saveSettings();
        this.refreshToolbar();
    }

    useColor(color) {
        if (this.selection) {
            const strokes = [...this.selection.strokes];
            this.doc.history.run(opRecolor(this.selection.page, strokes, color));
        } else {
            if (!INK_TOOLS.has(this.tool)) {
                this.setTool(this.settings.penKind || "pen");
            }
            this.toolState().c = color;
        }
        const recent = this.settings.recent.filter(item => item !== color);
        recent.unshift(color);
        this.settings.recent = recent.slice(0, 5);
        this.plugin.saveSettings();
        this.refreshToolbar();
    }

    onToolbarClick(event) {
        const button = event.target.closest("button");
        if (!button || button.disabled) {
            return;
        }
        const tool = button.dataset.tool;
        if (tool) {
            const active = button.classList.contains("kmg-ink__tool--on");
            if (tool === "pen") {
                if (active) {
                    this.openPenMenu(button);
                } else {
                    this.setTool(this.settings.penKind || "pen");
                }
            } else if (active && INK_TOOLS.has(tool)) {
                this.openSizeMenu(button);
            } else {
                this.setTool(tool);
            }
            return;
        }
        if (button.dataset.color) {
            this.useColor(button.dataset.color);
            return;
        }
        switch (button.dataset.action) {
            case "colors":
                this.openColorMenu(button);
                break;
            case "size":
                this.openSizeMenu(button);
                break;
            case "undo":
                this.clearSelection();
                this.doc.history.undo();
                break;
            case "redo":
                this.clearSelection();
                this.doc.history.redo();
                break;
            case "finger":
                this.settings.fingerDraw = this.settings.fingerDraw === false;
                this.plugin.saveSettings();
                this.refreshToolbar();
                break;
            case "paper":
                this.openPaperMenu(button);
                break;
            case "pages":
                this.openPagesMenu(button);
                break;
            case "fullscreen":
                this.plugin.openNotebookTab(this.file, this.blockId, this.blockElement);
                break;
            case "ask":
                this.ask("reply");
                break;
            case "quiz":
                this.ask("quiz");
                break;
        }
    }

    openPenMenu(anchor) {
        const i18n = this.i18n;
        const kinds = {pen: i18n.fountainPen, ball: i18n.ballpoint, shape: i18n.shapePen};
        const popover = openPopover(anchor, `<div class="kmg-ink-popover__row">${PEN_KINDS.map(kind =>
            `<button class="kmg-ink-popover__choice${this.tool === kind ? " kmg-ink-popover__choice--on" : ""}" data-kind="${kind}">${ICONS[kind]}<span>${kinds[kind]}</span></button>`).join("")}</div>
${this.sizeControls()}`);
        popover.addEventListener("click", (event) => {
            const kind = event.target.closest("[data-kind]")?.dataset.kind;
            if (kind) {
                this.setTool(kind);
                closePopover();
            }
        });
        this.bindSizeControls(popover);
    }

    sizeControls() {
        const tool = INK_TOOLS.has(this.tool) ? this.tool : this.settings.penKind || "pen";
        const spec = TOOLS[tool];
        const state = this.toolState(tool);
        return `<div class="kmg-ink-popover__title">${this.i18n.size}</div>
<div class="kmg-ink-popover__row">${spec.sizes.map(size =>
            `<button class="kmg-ink-popover__size${size === state.w ? " kmg-ink-popover__choice--on" : ""}" data-size="${size}"><span style="width:${Math.min(28, 4 + size * 28 / spec.max)}px;height:${Math.min(28, 4 + size * 28 / spec.max)}px"></span></button>`).join("")}</div>
<input class="kmg-ink-popover__range" type="range" min="${spec.min}" max="${spec.max}" step="1" value="${state.w}">`;
    }

    bindSizeControls(popover) {
        const tool = INK_TOOLS.has(this.tool) ? this.tool : this.settings.penKind || "pen";
        const set = (size) => {
            this.toolState(tool).w = size;
            this.plugin.saveSettings();
            popover.querySelectorAll("[data-size]").forEach(item =>
                item.classList.toggle("kmg-ink-popover__choice--on", Number(item.dataset.size) === size));
            popover.querySelector(".kmg-ink-popover__range").value = String(size);
        };
        popover.addEventListener("click", (event) => {
            const size = event.target.closest("[data-size]")?.dataset.size;
            if (size) {
                set(Number(size));
            }
        });
        popover.querySelector(".kmg-ink-popover__range").addEventListener("input", (event) => set(Number(event.target.value)));
    }

    openSizeMenu(anchor) {
        if (!INK_TOOLS.has(this.tool)) {
            this.setTool(this.settings.penKind || "pen");
        }
        const popover = openPopover(anchor, this.sizeControls());
        this.bindSizeControls(popover);
    }

    openColorMenu(anchor) {
        const i18n = this.i18n;
        const row = (title, colors) => colors.length ? `<div class="kmg-ink-popover__title">${title}</div><div class="kmg-ink-popover__row">${colors.map(color =>
            `<button class="kmg-ink__swatch" data-color="${color}" style="background:${color}" title="${color}"></button>`).join("")}</div>` : "";
        const state = this.toolState();
        const popover = openPopover(anchor, `${row(i18n.recentColors, this.settings.recent)}
${row(i18n.colors, PALETTE.main)}${row(i18n.pastel, PALETTE.pastel)}${row(i18n.greys, PALETTE.grey)}
<label class="kmg-ink-popover__custom">${i18n.customColor} <input type="color" value="${state.c}"></label>`);
        popover.addEventListener("click", (event) => {
            const color = event.target.closest("[data-color]")?.dataset.color;
            if (color) {
                this.useColor(color);
                closePopover();
            }
        });
        popover.querySelector("input[type=color]").addEventListener("change", (event) => {
            this.useColor(event.target.value);
            closePopover();
        });
    }

    openPaperMenu(anchor) {
        const i18n = this.i18n;
        const paper = this.doc.data.paper;
        const names = {
            blank: i18n.patternBlank, lined: i18n.patternLined, college: i18n.patternCollege, grid: i18n.patternGrid,
            dots: i18n.patternDots, staffs: i18n.patternStaffs, tablature: i18n.patternTablature, cornell: i18n.patternCornell,
        };
        const popover = openPopover(anchor, `<div class="kmg-ink-popover__title">${i18n.paper}</div>
<div class="kmg-ink-popover__grid">${PATTERNS.map(pattern => `<button class="kmg-ink-popover__pattern${paper.pattern === pattern ? " kmg-ink-popover__choice--on" : ""}" data-pattern="${pattern}"><canvas width="84" height="112"></canvas><span>${names[pattern]}</span></button>`).join("")}</div>
<label class="kmg-ink-popover__label">${i18n.lineHeight} <input type="range" data-paper="line" min="20" max="100" step="5" value="${paper.line}"></label>
<label class="kmg-ink-popover__label">${i18n.lineThickness} <input type="range" data-paper="thick" min="1" max="5" step="0.5" value="${paper.thick}"></label>
<div class="kmg-ink-popover__title">${i18n.paperColor}</div>
<div class="kmg-ink-popover__row">${Object.keys(PAPER_COLORS).map(key => `<button class="kmg-ink-popover__choice${paper.color === key ? " kmg-ink-popover__choice--on" : ""}" data-paper-color="${key}"><span class="kmg-ink__swatch" style="background:${PAPER_COLORS[key].fill}"></span><span>${i18n["paper_" + key]}</span></button>`).join("")}</div>
${this.plugin.pdfImport ? `<button class="kmg-ink-popover__wide" data-action="import-pdf">${ICONS.pdf}<span>${i18n.importPdf}</span></button>` : ""}`, "kmg-ink-popover--paper");
        const previews = () => popover.querySelectorAll("[data-pattern]").forEach(item => {
            const canvas = item.querySelector("canvas");
            const ctx = canvas.getContext("2d");
            ctx.setTransform(84 / PAGE_W, 0, 0, 84 / PAGE_W, 0, 0);
            drawPaper(ctx, {w: PAGE_W, h: PAGE_H, bg: null}, {...this.doc.data.paper, pattern: item.dataset.pattern});
        });
        previews();
        const change = (patch) => {
            const next = {...this.doc.data.paper, ...patch};
            this.doc.history.run(opPaper(this.doc.data, next));
            this.settings.paper = next;
            this.plugin.saveSettings();
            popover.querySelectorAll("[data-pattern]").forEach(item =>
                item.classList.toggle("kmg-ink-popover__choice--on", item.dataset.pattern === next.pattern));
            popover.querySelectorAll("[data-paper-color]").forEach(item =>
                item.classList.toggle("kmg-ink-popover__choice--on", item.dataset.paperColor === next.color));
            previews();
        };
        popover.addEventListener("click", (event) => {
            const pattern = event.target.closest("[data-pattern]")?.dataset.pattern;
            const color = event.target.closest("[data-paper-color]")?.dataset.paperColor;
            if (pattern) {
                change({pattern});
            } else if (color) {
                change({color});
            } else if (event.target.closest('[data-action="import-pdf"]')) {
                closePopover();
                this.plugin.pdfImport(this);
            }
        });
        popover.querySelectorAll("input[data-paper]").forEach(input => input.addEventListener("change", () =>
            change({[input.dataset.paper]: Number(input.value)})));
    }

    openPagesMenu(anchor) {
        const i18n = this.i18n;
        const popover = openPopover(anchor, `<div class="kmg-ink-popover__title">${i18n.pages}</div><div class="kmg-ink-popover__pages"></div>`, "kmg-ink-popover--pages");
        const list = popover.querySelector(".kmg-ink-popover__pages");
        const render = () => {
            const pages = this.doc.data.pages;
            list.innerHTML = pages.map((page, index) => `<div class="kmg-ink-popover__page" data-index="${index}">
    <canvas class="kmg-ink-popover__thumb" data-go="${index}" width="${Math.round(70 * page.w / page.h * 1.4)}" height="98" title="${i18n.goToPage}"></canvas>
    <span class="kmg-ink-popover__pageno">${index + 1}</span>
    <span class="kmg-ink__spacer"></span>
    <button data-page-op="up" title="${i18n.moveUp}" ${index === 0 ? "disabled" : ""}>${ICONS.up}</button>
    <button data-page-op="down" title="${i18n.moveDown}" ${index === pages.length - 1 ? "disabled" : ""}>${ICONS.down}</button>
    <button data-page-op="insert" title="${i18n.insertPageAfter}">${ICONS.add}</button>
    <button data-page-op="duplicate" title="${i18n.duplicatePage}">${ICONS.copy}</button>
    <button data-page-op="clear" title="${i18n.clearPage}">${ICONS.clear}</button>
    <button data-page-op="delete" title="${i18n.deletePage}" ${pages.length === 1 ? "disabled" : ""}>${ICONS.trash}</button>
</div>`).join("");
            list.querySelectorAll("canvas").forEach(canvas => {
                const page = pages[Number(canvas.dataset.go)];
                const ctx = canvas.getContext("2d");
                const s = canvas.width / page.w;
                ctx.setTransform(s, 0, 0, s, 0, 0);
                drawPaper(ctx, page, this.doc.data.paper);
                const view = this.views.get(page.id);
                if (view?.size && page.bg) {
                    ctx.setTransform(1, 0, 0, 1, 0, 0);
                    ctx.drawImage(view.bg, 0, 0, canvas.width, canvas.height);
                    ctx.setTransform(s, 0, 0, s, 0, 0);
                }
                drawHighlights(ctx, page, this.doc.data.paper);
                drawInk(ctx, page, this.doc.data.paper);
            });
        };
        render();
        popover.addEventListener("click", (event) => {
            const go = event.target.closest("[data-go]")?.dataset.go;
            if (go !== undefined) {
                const page = this.doc.data.pages[Number(go)];
                this.views.get(page.id)?.el.scrollIntoView({block: "start", behavior: "smooth"});
                return;
            }
            const button = event.target.closest("[data-page-op]");
            if (!button) {
                return;
            }
            const index = Number(button.closest("[data-index]").dataset.index);
            this.pageOperation(button.dataset.pageOp, index);
            render();
        });
    }

    pageOperation(operation, index) {
        const data = this.doc.data;
        const before = data.pages.slice();
        const after = data.pages.slice();
        const page = after[index];
        switch (operation) {
            case "up":
                after.splice(index - 1, 0, after.splice(index, 1)[0]);
                break;
            case "down":
                after.splice(index + 1, 0, after.splice(index, 1)[0]);
                break;
            case "insert":
                after.splice(index + 1, 0, emptyPage(page.w, page.h));
                break;
            case "duplicate": {
                const copy = JSON.parse(JSON.stringify(page));
                copy.id = shortId();
                copy.items = [];
                copy.strokes.forEach(stroke => {
                    stroke.id = shortId();
                    stroke.sent = false;
                });
                after.splice(index + 1, 0, copy);
                break;
            }
            case "delete":
                after.splice(index, 1);
                break;
            case "clear": {
                // A cleared page is a new, empty page object in the same place, so undo brings the old one back.
                const cleared = emptyPage(page.w, page.h);
                cleared.bg = page.bg;
                after.splice(index, 1, cleared);
                break;
            }
        }
        this.clearSelection();
        this.doc.history.run(opPages(data, before, after));
        if (this.doc.ensureTrailingPage()) {
            this.doc.changed({pages: "all", structure: true});
        }
    }

    // ---- changes from the doc ----

    applyChange(detail) {
        if (!this.root) {
            return;
        }
        if (detail.structure) {
            this.syncPages();
        }
        if (detail.pages === "all") {
            this.views.forEach(view => view.visible && this.markDirty(view));
        } else {
            detail.pages.forEach(id => {
                const view = this.views.get(id);
                if (view?.visible) {
                    this.markDirty(view);
                }
            });
        }
        this.updateHistoryButtons();
    }

    // ---- input ----

    pagePoint(event, view) {
        const rect = view.el.getBoundingClientRect();
        const s = rect.width / view.page.w;
        return [
            Math.round((event.clientX - rect.left) / s * 10) / 10,
            Math.round((event.clientY - rect.top) / s * 10) / 10,
            event.pointerType === "pen" ? Math.round((event.pressure || 0.5) * 100) / 100 : 0.5,
        ];
    }

    viewAt(event) {
        const el = event.target.closest?.(".kmg-ink__page");
        return el ? this.views.get(el.dataset.page) : null;
    }

    scroller() {
        return this.mode === "tab" ? this.scrollEl : this.host.closest(".protyle-content");
    }

    onPointerDown(event) {
        if (event.target.closest(".kmg-ink__selbar")) {
            return;
        }
        const view = this.viewAt(event);
        if (!view || this.doc.busy) {
            return;
        }
        if (event.pointerType === "mouse" && event.button !== 0) {
            return;
        }
        if (event.pointerType === "touch") {
            this.touches.set(event.pointerId, {x: event.clientX, y: event.clientY});
            this.pagesEl.setPointerCapture(event.pointerId);
            if (this.current?.pointerType === "touch") {
                this.cancelCurrent(); // a second finger: the first was not drawing
            }
            if (this.settings.fingerDraw === false || this.touches.size > 1 || this.current) {
                event.preventDefault();
                this.startGesture();
                return;
            }
        }
        if (event.pointerType === "pen" && !this.penSeen) {
            this.penSeen = true;
            if (this.settings.fingerDraw !== false && this.settings.fingerAuto !== false) {
                this.settings.fingerDraw = false;
                this.plugin.saveSettings();
                this.refreshToolbar();
            }
        }
        if (this.current) {
            return;
        }
        event.preventDefault();
        this.pagesEl.setPointerCapture(event.pointerId);
        this.root.focus({preventScroll: true});
        closePopover();
        const point = this.pagePoint(event, view);
        const base = {id: event.pointerId, pointerType: event.pointerType, view};
        const penEraser = event.pointerType === "pen" && (event.button === 5 || (event.buttons & 32) || (event.buttons & 2));
        if (this.tool === "eraser" || penEraser) {
            this.current = {...base, kind: "erase", original: view.page.strokes.slice(), last: point};
            this.eraseAt(view, point);
            return;
        }
        if (this.tool === "lasso") {
            const selection = this.selection;
            if (selection && selection.page === view.page && selection.bounds) {
                const b = selection.bounds;
                const s = view.el.clientWidth / view.page.w;
                const handle = Math.hypot(point[0] - b.maxX, point[1] - b.maxY) < 22 / s;
                const inside = point[0] >= b.minX && point[0] <= b.maxX && point[1] >= b.minY && point[1] <= b.maxY;
                if (handle || inside) {
                    const strokes = [...selection.strokes];
                    this.current = {
                        ...base,
                        kind: handle ? "scale" : "move",
                        start: point,
                        bounds: {...b},
                        before: strokes.map(stroke => ({stroke, p: stroke.p, sh: stroke.sh})),
                    };
                    this.renderSelection(view, s);
                    return;
                }
            }
            this.clearSelection();
            this.current = {...base, kind: "lasso", points: [point]};
            this.attachLive(view);
            return;
        }
        const tool = this.tool;
        const state = this.toolState(tool);
        const stroke = {id: shortId(), t: tool, c: state.c, w: state.w, p: [point], pr: event.pointerType === "pen"};
        this.current = {...base, kind: "ink", stroke, anchor: point};
        this.attachLive(view);
        this.armHold();
    }

    onPointerMove(event) {
        if (this.touches.has(event.pointerId) && (!this.current || this.current.id !== event.pointerId)) {
            this.touches.set(event.pointerId, {x: event.clientX, y: event.clientY});
            if (this.gesture) {
                event.preventDefault();
                this.updateGesture();
            }
            return;
        }
        const current = this.current;
        if (!current || current.id !== event.pointerId) {
            return;
        }
        event.preventDefault();
        const events = event.getCoalescedEvents ? event.getCoalescedEvents() : [event];
        const view = current.view;
        for (const item of events.length ? events : [event]) {
            const point = this.pagePoint(item, view);
            if (current.kind === "erase") {
                // Pointer events can be far apart on a fast swipe: erase along the way.
                const steps = Math.max(1, Math.ceil(dist(current.last, point) / 5));
                for (let i = 1; i <= steps; i++) {
                    const t = i / steps;
                    this.eraseAt(view, [current.last[0] + (point[0] - current.last[0]) * t, current.last[1] + (point[1] - current.last[1]) * t]);
                }
                current.last = point;
            } else if (current.kind === "lasso") {
                current.points.push(point);
            } else if (current.kind === "ink") {
                if (current.frozen) {
                    break;
                }
                const points = current.stroke.p;
                const last = points[points.length - 1];
                if (Math.abs(last[0] - point[0]) + Math.abs(last[1] - point[1]) < 0.8) {
                    continue;
                }
                points.push(point);
                if (dist(point, current.anchor) > 4) {
                    current.anchor = point;
                    this.armHold();
                }
            } else {
                this.transformSelection(point);
            }
        }
        if (current.kind === "ink") {
            forgetOutline(current.stroke);
        }
        if (current.kind === "ink" || current.kind === "lasso") {
            this.scheduleLive();
        }
    }

    onPointerUp(event, cancelled = false) {
        if (this.touches.has(event.pointerId)) {
            this.touches.delete(event.pointerId);
            if (this.gesture && (!this.current || this.current.id !== event.pointerId)) {
                if (this.touches.size === 0) {
                    this.gesture = null;
                    this.layout();
                } else {
                    this.startGesture();
                }
                return;
            }
        }
        const current = this.current;
        if (!current || current.id !== event.pointerId) {
            return;
        }
        clearTimeout(this.holdTimer);
        this.current = null;
        this.detachLive();
        const view = current.view;
        const page = view.page;
        if (current.kind === "ink") {
            if (cancelled && current.pointerType === "touch") {
                return;
            }
            const stroke = current.stroke;
            const shape = current.shape || (stroke.t === "shape" ? recognizeShape(stroke.p) : null);
            if (shape) {
                stroke.sh = shape;
                stroke.p = shapePoints(shape);
            }
            if (stroke.t === "shape" && !stroke.sh) {
                stroke.t = "ball"; // an unrecognised shape stays as drawn
            }
            forgetOutline(stroke);
            this.doc.history.run(opAddStroke(page, stroke));
            if (this.doc.ensureTrailingPage()) {
                this.doc.changed({pages: "all", structure: true});
            }
        } else if (current.kind === "erase") {
            const remaining = new Set(page.strokes);
            const removed = current.original.map((stroke, index) => ({stroke, index})).filter(item => !remaining.has(item.stroke));
            if (removed.length) {
                this.doc.history.push(opRemoveStrokes(page, removed));
            }
        } else if (current.kind === "lasso") {
            const polygon = current.points;
            const strokes = polygon.length > 2 ? page.strokes.filter(stroke =>
                stroke.p.filter(point => pointInPolygon(point, polygon)).length >= stroke.p.length * 0.7) : [];
            this.selection = strokes.length ? {page, strokes: new Set(strokes), polygon} : null;
            this.onLassoDone?.(view, polygon, strokes);
            this.markDirty(view);
        } else if (current.kind === "move" || current.kind === "scale") {
            const after = current.before.map(({stroke}) => ({stroke, p: stroke.p, sh: stroke.sh}));
            const moved = after.some((item, index) => item.p !== current.before[index].p);
            if (moved) {
                this.doc.history.push(opReshape(page, current.before, after));
            } else {
                this.markDirty(view);
            }
        }
    }

    cancelCurrent() {
        const current = this.current;
        if (!current) {
            return;
        }
        clearTimeout(this.holdTimer);
        this.current = null;
        this.detachLive();
        if (current.kind === "move" || current.kind === "scale") {
            current.before.forEach(({stroke, p, sh}) => {
                stroke.p = p;
                stroke.sh = sh;
                forgetOutline(stroke);
            });
        }
        if (current.kind === "erase") {
            current.view.page.strokes = current.original;
        }
        this.markDirty(current.view);
    }

    armHold() {
        clearTimeout(this.holdTimer);
        this.holdTimer = setTimeout(() => {
            const current = this.current;
            if (current?.kind !== "ink" || current.stroke.p.length < 3) {
                return;
            }
            const shape = recognizeShape(current.stroke.p, true);
            if (shape) {
                current.shape = shape;
                current.frozen = true;
                this.scheduleLive();
            }
        }, HOLD_DELAY);
    }

    eraseAt(view, [x, y]) {
        const page = view.page;
        const radius = 10;
        const before = page.strokes.length;
        page.strokes = page.strokes.filter(stroke => !strokeHit(stroke, x, y, radius));
        if (page.strokes.length !== before) {
            this.markDirty(view);
        }
    }

    transformSelection(point) {
        const current = this.current;
        const b = current.bounds;
        let map;
        let factor = 1;
        if (current.kind === "move") {
            const dx = point[0] - current.start[0];
            const dy = point[1] - current.start[1];
            map = (x, y) => [x + dx, y + dy];
        } else {
            const start = Math.hypot(current.start[0] - b.minX, current.start[1] - b.minY);
            factor = clamp(Math.hypot(point[0] - b.minX, point[1] - b.minY) / (start || 1), 0.1, 10);
            map = (x, y) => [b.minX + (x - b.minX) * factor, b.minY + (y - b.minY) * factor];
        }
        current.before.forEach(({stroke, p, sh}) => {
            stroke.p = p.map(([x, y, pressure]) => [...map(x, y), pressure]);
            if (sh) {
                stroke.sh = mapShape(sh, map, factor);
            }
            forgetOutline(stroke);
        });
        this.markDirty(current.view);
    }

    clearSelection() {
        if (!this.selection) {
            return;
        }
        const view = this.views.get(this.selection.page.id);
        this.selection = null;
        if (view) {
            this.markDirty(view);
        }
    }

    onPagesClick(event) {
        const button = event.target.closest("[data-sel]");
        if (button) {
            this.selectionAction(button.dataset.sel);
        }
    }

    selectionAction(action) {
        if (!this.selection) {
            return;
        }
        const {page, strokes} = this.selection;
        const list = [...strokes];
        switch (action) {
            case "delete": {
                const removed = page.strokes.map((stroke, index) => ({stroke, index})).filter(item => strokes.has(item.stroke));
                this.selection = null;
                this.doc.history.run(opRemoveStrokes(page, removed));
                break;
            }
            case "duplicate": {
                const copies = list.map(stroke => {
                    const copy = JSON.parse(JSON.stringify(stroke));
                    copy.id = shortId();
                    copy.sent = false;
                    copy.p = copy.p.map(([x, y, pressure]) => [x + 25, y + 25, pressure]);
                    copy.sh = mapShape(copy.sh, (x, y) => [x + 25, y + 25]);
                    return copy;
                });
                this.doc.history.run({
                    detail: {pages: [page.id]},
                    apply: () => page.strokes.push(...copies),
                    revert: () => {
                        const gone = new Set(copies);
                        page.strokes = page.strokes.filter(stroke => !gone.has(stroke));
                    },
                });
                this.selection = {page, strokes: new Set(copies)};
                break;
            }
            case "explain":
                this.plugin.explainSelection(this, this.selection);
                break;
        }
    }

    onKeyDown(event) {
        const mod = event.ctrlKey || event.metaKey;
        const key = event.key.toLowerCase();
        let handled = true;
        if (mod && key === "z" && !event.shiftKey) {
            this.clearSelection();
            this.doc.history.undo();
        } else if (mod && (key === "y" || (key === "z" && event.shiftKey))) {
            this.clearSelection();
            this.doc.history.redo();
        } else if (mod && key === "e") {
            this.setTool("eraser");
        } else if ((key === "delete" || key === "backspace") && this.selection) {
            this.selectionAction("delete");
        } else if (key === "escape" && this.selection) {
            this.clearSelection();
        } else if (mod && (key === "=" || key === "+") && this.mode === "tab") {
            this.setZoom(this.zoom + 0.1);
        } else if (mod && key === "-" && this.mode === "tab") {
            this.setZoom(this.zoom - 0.1);
        } else {
            handled = false;
        }
        if (handled) {
            event.preventDefault();
            event.stopPropagation();
        }
    }

    // ---- live drawing ----

    attachLive(view) {
        const {ratio, width, height} = this.canvasMetrics(view);
        this.live.width = width;
        this.live.height = height;
        this.live.dataset.ratio = String(ratio);
        this.live.classList.toggle("kmg-ink__live--hl", this.current?.stroke?.t === "hl");
        view.el.append(this.live);
    }

    detachLive() {
        cancelAnimationFrame(this.liveFrame);
        this.liveFrame = 0;
        this.live.remove();
    }

    scheduleLive() {
        if (!this.liveFrame) {
            this.liveFrame = requestAnimationFrame(() => {
                this.liveFrame = 0;
                this.drawLive();
            });
        }
    }

    drawLive() {
        const current = this.current;
        if (!current) {
            return;
        }
        const view = current.view;
        const s = view.el.clientWidth / view.page.w;
        const ratio = Number(this.live.dataset.ratio) || 1;
        const ctx = this.live.getContext("2d");
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, this.live.width, this.live.height);
        ctx.setTransform(ratio * s, 0, 0, ratio * s, 0, 0);
        const paper = this.doc.data.paper;
        if (current.kind === "ink") {
            const stroke = current.shape ?
                {...current.stroke, sh: current.shape, p: shapePoints(current.shape)} : current.stroke;
            drawStroke(ctx, stroke, paper);
        } else if (current.kind === "lasso") {
            ctx.save();
            ctx.strokeStyle = "#3573f0";
            ctx.lineWidth = 2 / s;
            ctx.setLineDash([8 / s, 6 / s]);
            ctx.fillStyle = "rgba(53, 115, 240, .08)";
            ctx.beginPath();
            current.points.forEach(([x, y], index) => index ? ctx.lineTo(x, y) : ctx.moveTo(x, y));
            ctx.closePath();
            ctx.fill();
            ctx.stroke();
            ctx.restore();
        }
    }

    // ---- gestures: fingers pan, two fingers pinch (zoom in the tab) ----

    startGesture() {
        const points = [...this.touches.values()];
        const mid = points.reduce((acc, p) => ({x: acc.x + p.x / points.length, y: acc.y + p.y / points.length}), {x: 0, y: 0});
        const spread = points.length > 1 ? Math.hypot(points[0].x - points[1].x, points[0].y - points[1].y) : 0;
        this.gesture = {mid, spread, zoom: this.zoom};
    }

    updateGesture() {
        const gesture = this.gesture;
        const points = [...this.touches.values()];
        if (!points.length) {
            return;
        }
        const mid = points.reduce((acc, p) => ({x: acc.x + p.x / points.length, y: acc.y + p.y / points.length}), {x: 0, y: 0});
        const scroller = this.scroller();
        if (scroller) {
            scroller.scrollBy(gesture.mid.x - mid.x, gesture.mid.y - mid.y);
        }
        gesture.mid = mid;
        if (this.mode === "tab" && points.length > 1 && gesture.spread > 0) {
            const spread = Math.hypot(points[0].x - points[1].x, points[0].y - points[1].y);
            this.setZoom(gesture.zoom * spread / gesture.spread, mid, false);
        }
    }

    onWheel(event) {
        if (!event.ctrlKey && !event.metaKey) {
            return;
        }
        event.preventDefault();
        this.setZoom(this.zoom * Math.exp(-event.deltaY * 0.002), {x: event.clientX, y: event.clientY});
    }

    setZoom(value, anchor, snap = true) {
        const zoom = clamp(value, 0.5, 4);
        const scroller = this.scrollEl;
        const rect = scroller.getBoundingClientRect();
        const ax = anchor ? anchor.x - rect.left : rect.width / 2;
        const ay = anchor ? anchor.y - rect.top : rect.height / 2;
        const fx = (scroller.scrollLeft + ax) / Math.max(1, scroller.scrollWidth);
        const fy = (scroller.scrollTop + ay) / Math.max(1, scroller.scrollHeight);
        this.zoom = zoom;
        this.layout();
        scroller.scrollLeft = fx * scroller.scrollWidth - ax;
        scroller.scrollTop = fy * scroller.scrollHeight - ay;
        clearTimeout(this.zoomSnap);
        if (snap && zoom !== 1 && Math.abs(zoom - 1) < 0.05) {
            this.zoomSnap = setTimeout(() => this.setZoom(1, anchor, false), 200);
        }
    }

    // ---- the AI ----

    async ask(mode) {
        const doc = this.doc;
        if (doc.busy) {
            return;
        }
        const i18n = this.i18n;
        const pages = doc.data.pages;
        const fresh = pages.map(page => ({page, strokes: page.strokes.filter(stroke => !stroke.sent && stroke.t !== "hl")}))
            .filter(group => group.strokes.length);
        if (fresh.length === 0 && mode !== "quiz") {
            showMessage(i18n.writeFirst);
            return;
        }
        this.clearSelection();
        doc.busy = true;
        doc.dispatchEvent(new CustomEvent("status"));
        const history = pages.flatMap(page => page.items).map(item => ({
            role: item.type === "reply" ? "assistant" : "user",
            content: item.text,
        }));
        try {
            const canvases = fresh.slice(-4).map(group => renderStrokesImage(group.strokes, doc.data.paper)).filter(Boolean);
            const context = this.blockElement?.isConnected ?
                documentContext(this.blockElement) : await documentContextById(this.blockId || doc.blockId);
            const result = await askAI({
                images: canvases.length ? [stackImages(canvases)] : [],
                text: mode === "quiz" && fresh.length === 0 ? i18n.quizStart : "",
                context,
                mode,
                history,
            });
            const target = fresh.length ? fresh[fresh.length - 1].page :
                [...pages].reverse().find(page => !pageIsEmpty(page)) || pages[0];
            const paper = doc.data.paper;
            const writing = strokeBounds(target.strokes.filter(stroke => stroke.t !== "hl" &&
                (fresh.length ? fresh[fresh.length - 1].strokes.includes(stroke) : true)));
            const lastReply = [...target.items].reverse().find(item => item.type === "reply");
            const bottom = Math.max(writing ? writing.maxY : 0, lastReply ? lastReply.y + lastReply.h : 0,
                (paper.top ?? 2) * paper.line - paper.line);
            let lineY = snapToLine(paper, bottom + paper.line * 0.5);
            if (lineY - bottom < paper.line * 0.9) {
                lineY += paper.line;
            }
            if (result.transcript) {
                target.items.push({type: "note", text: result.transcript});
            } else if (fresh.length) {
                showMessage(i18n.noTranscript, 6000);
            }
            const reply = {type: "reply", text: result.reply, y: this.replyTop(lineY, bottom), h: 0, mode};
            target.items.push(reply);
            fresh.forEach(group => group.strokes.forEach(stroke => {
                stroke.sent = true;
            }));
            const view = this.views.get(target.id);
            if (view) {
                view.freshReply = reply;
            }
            doc.ensureTrailingPage();
            doc.changed({pages: "all", structure: true}, false);
            await doc.save();
            this.plugin.writeConversation(doc);
        } catch (error) {
            showMessage(`${i18n.askFailed} ${error.message}`, 7000, "error");
        } finally {
            doc.busy = false;
            doc.dispatchEvent(new CustomEvent("status"));
        }
    }
}

// ---- src/90-plugin.js ----

// The plugin: the note block, the full-screen tab, settings, and "Discuss with AI" in the PDF viewer.

const DEFAULT_SETTINGS = {
    tool: "pen",
    penKind: "pen",
    tools: {},
    recent: ["#1b1b1b", "#1f4fbf", "#c62828"],
    fingerDraw: true,
    fingerAuto: true,
    paper: DEFAULT_PAPER,
};

module.exports = class KmgInk extends Plugin {
    onload() {
        this.addIcons(`<symbol id="iconKmgInk" viewBox="0 0 32 32"><path d="M25.4 3.2a3 3 0 0 1 4.2 4.2L13 24l-6.4 2.2L8.8 19.8zM6 28h20v2H6z"/></symbol>`);
        const i18n = this.i18n;
        // Views wait for settingsReady; the renderers are registered at once so no block misses them.
        this.settings = JSON.parse(JSON.stringify(DEFAULT_SETTINGS));
        this.views = new Set();
        this.settingsReady = this.loadData("settings.json").then(saved => {
            Object.assign(this.settings, saved || {});
            this.settings.tools = this.settings.tools || {};
        }).catch(() => null);

        this.customBlockRenders[BLOCK] = {
            render: (options) => this.renderBlock(options),
        };

        this.protyleSlash = [{
            filter: ["ink", "handwriting", "hand", "pen", "notebook", "draw by hand"],
            html: `<div class="b3-list-item__first"><svg class="b3-list-item__graphic"><use xlink:href="#iconKmgInk"></use></svg><span class="b3-list-item__text">${i18n.handwritingPage}</span></div>`,
            id: "insertPage",
            callback: (protyle, nodeElement) => this.insertPage(nodeElement),
        }];

        this.addCommand({
            langKey: "insertPage",
            hotkey: "",
            editorCallback: () => {
                const range = window.getSelection()?.rangeCount ? window.getSelection().getRangeAt(0) : null;
                const node = range?.startContainer?.parentElement?.closest("[data-node-id]");
                if (node) {
                    this.insertPage(node);
                }
            },
        });

        const plugin = this;
        this.addTab({
            type: TAB,
            init() {
                const host = document.createElement("div");
                host.className = "kmg-ink-tab";
                this.element.append(host);
                this.notebook = new NotebookView({
                    plugin, element: host, file: this.data.file, mode: "tab", blockId: this.data.blockId,
                });
                this.notebook.start();
            },
            destroy() {
                this.notebook?.dispose();
            },
        });

        this.onPdfClick = (event) => {
            const rect = event.target.closest?.(".pdf__rect");
            if (rect) {
                this.lastAnnotation = rect;
            }
        };
        document.addEventListener("pointerdown", this.onPdfClick, true);
        this.pdfObserver = new MutationObserver(() => this.addPdfButtons());
        this.pdfObserver.observe(document.body, {childList: true, subtree: true});
    }

    onunload() {
        // Open notebooks close and save now, so a reloaded plugin reads what they wrote.
        const saves = [...this.views].map(view => view.dispose());
        if (this.settingsTimer) {
            clearTimeout(this.settingsTimer);
            saves.push(this.saveData("settings.json", this.settings));
        }
        window[FLUSH] = Promise.all(saves).catch(() => null);
        closePopover();
        document.removeEventListener("pointerdown", this.onPdfClick, true);
        this.pdfObserver?.disconnect();
        document.querySelectorAll(".kmg-ink-pdf-button").forEach(item => item.remove());
    }

    // Settings changed elsewhere (sync, another window): take them over instead of letting KMG
    // reload the plugin, which would close every open notebook.
    async onDataChanged() {
        const saved = await this.loadData("settings.json").catch(() => null);
        if (saved) {
            Object.assign(this.settings, saved);
        }
    }

    saveSettings() {
        clearTimeout(this.settingsTimer);
        this.settingsTimer = setTimeout(() => {
            this.settingsTimer = 0;
            this.saveData("settings.json", this.settings);
        }, 600);
    }

    async insertPage(nodeElement) {
        const file = `assets/kmg-ink/${newId()}.json`;
        await saveNotebook(file, newNotebook(this.settings.paper));
        const id = nodeElement.getAttribute("data-node-id");
        const leftover = (nodeElement.textContent || "").replace(/[/、][^\s/]*$/, "").trim();
        if (nodeElement.getAttribute("data-type") === "NodeParagraph" && !leftover) {
            fetchPost("/api/block/updateBlock", {dataType: "markdown", data: pageMarkdown(file), id});
        } else {
            fetchPost("/api/block/insertBlock", {dataType: "markdown", data: pageMarkdown(file), previousID: id});
        }
    }

    renderBlock({element, content, setContent}) {
        const {meta, text} = parseContent(content);
        if (!meta?.file) {
            element.innerHTML = `<div class="kmg-ink__error">${this.i18n.brokenPage}</div><pre>${escapeHtml(text)}</pre>`;
            return;
        }
        const blockElement = element.closest('[data-type="NodeCustomBlock"]');
        const view = new NotebookView({
            plugin: this,
            element,
            file: meta.file,
            mode: "block",
            blockId: blockElement?.getAttribute("data-node-id") || "",
            blockElement,
            setContent,
        });
        view.start();
        return () => view.dispose();
    }

    openNotebookTab(file, blockId, blockElement) {
        const title = blockElement?.closest(".protyle")?.querySelector(".protyle-title__input")?.textContent?.trim();
        openTab({
            app: this.app,
            custom: {
                id: this.name + TAB,
                icon: "iconKmgInk",
                title: title || this.i18n.handwritingPage,
                data: {file, blockId},
            },
        });
    }

    // The block's text carries the conversation for search.
    writeConversation(doc) {
        const writer = doc.blockWriters && [...doc.blockWriters][0];
        if (writer) {
            writer();
        } else if (doc.blockId) {
            fetchPost("/api/block/updateBlock", {
                dataType: "markdown",
                data: pageMarkdown(doc.file, conversationText(doc.data)),
                id: doc.blockId,
            });
        }
    }

    // "Discuss with AI" in the PDF selection popup.
    addPdfButtons() {
        document.querySelectorAll(".pdf__util").forEach(util => {
            if (util.querySelector(".kmg-ink-pdf-button")) {
                return;
            }
            const button = document.createElement("button");
            button.className = "b3-menu__item kmg-ink-pdf-button";
            button.innerHTML = `<svg class="b3-menu__icon"><use xlink:href="#iconKmgInk"></use></svg><span class="b3-menu__label">${this.i18n.discuss}</span>`;
            button.addEventListener("mousedown", event => event.preventDefault());
            button.addEventListener("click", event => {
                event.stopPropagation();
                this.discussPdf(util);
            });
            util.append(button);
        });
    }

    findPdfAsset(element) {
        const model = (getAllModels().asset || []).find(item => item.element?.contains(element));
        return model?.path || "";
    }

    async discussPdf(util) {
        const i18n = this.i18n;
        const selection = window.getSelection()?.toString().trim() || "";
        const annotation = util.classList.contains("pdf__util--hide") ? null : this.lastAnnotation;
        const quote = selection || annotation?.getAttribute("data-content") || "";
        util.classList.add("fn__none");
        if (!quote) {
            showMessage(i18n.selectFirst);
            return;
        }
        const pdfPath = this.findPdfAsset(util);
        const pageText = util.closest(".pdf__outer")?.querySelector(".page[data-loaded] .textLayer")?.textContent || "";
        await this.createDiscussion({
            quote,
            pdfPath,
            annotationId: annotation?.getAttribute("data-node-id"),
            request: {text: quote, context: pageText.slice(0, MAX_CONTEXT), mode: "discuss", history: []},
        });
    }

    // A note under "AI discussions / <PDF name>" with the quote, a link back and a notebook holding the AI's reply.
    async createDiscussion({quote, pdfPath, annotationId, request, result}) {
        const i18n = this.i18n;
        const pdfName = decodeURIComponent((pdfPath.split("/").pop() || "PDF").replace(/\.pdf$/i, ""))
            .replace(/-\d{14}-[a-z0-9]{7}$/, "");
        const refLine = annotationId && pdfPath ? `<<${pdfPath}/${annotationId} "${pdfName}">>` : (pdfPath ? `[${pdfName}](${pdfPath})` : "");
        const notebook = await this.pickNotebook();
        if (!notebook) {
            return;
        }
        if (!result) {
            showMessage(i18n.thinking, -1, "info", "kmg-ink-thinking");
            try {
                result = await askAI(request);
            } catch (error) {
                showMessage(`${i18n.askFailed} ${error.message}`, 7000, "error");
                return;
            } finally {
                hideMessage("kmg-ink-thinking");
            }
        }
        const file = `assets/kmg-ink/${newId()}.json`;
        const data = newNotebook(this.settings.paper);
        data.pages[0].items.push({type: "note", text: quote}, {type: "reply", text: result.reply, y: 40, h: 0, mode: request?.mode || "discuss"});
        data.pages.push(emptyPage());
        await saveNotebook(file, data);
        const title = quote.replace(/\s+/g, " ").slice(0, 60).replace(/[/\\]/g, "-") || pdfName;
        const markdown = [
            `> ${quote.replace(/\n/g, "\n> ")}`,
            "",
            refLine,
            "",
            pageMarkdown(file, conversationText(data)),
            "",
        ].join("\n");
        const response = await fetchSyncPost("/api/filetree/createDocWithMd", {
            notebook,
            path: `/${i18n.discussionsFolder}/${pdfName.replace(/[/\\]/g, "-")}/${title}`,
            markdown,
        });
        if (response.code !== 0) {
            showMessage(response.msg, 7000, "error");
            return;
        }
        const id = response.data;
        if (isMobile()) {
            openMobileFileById(this.app, id);
        } else {
            openTab({app: this.app, doc: {id}, position: "right"});
        }
    }

    async pickNotebook() {
        const response = await fetchSyncPost("/api/notebook/lsNotebooks", {});
        const notebooks = (response.data?.notebooks || []).filter(item => !item.closed);
        if (notebooks.length === 0) {
            showMessage(this.i18n.noNotebook);
            return "";
        }
        if (notebooks.some(item => item.id === this.settings.notebook)) {
            return this.settings.notebook;
        }
        if (notebooks.length === 1) {
            return notebooks[0].id;
        }
        return new Promise(resolve => {
            let chosen = "";
            const dialog = new Dialog({
                title: this.i18n.chooseNotebook,
                content: `<div class="b3-dialog__content"><select class="b3-select fn__block">${notebooks.map(item =>
                    `<option value="${item.id}">${escapeHtml(item.name)}</option>`).join("")}</select></div>
<div class="b3-dialog__action"><button class="b3-button b3-button--cancel">${window.siyuan.languages.cancel}</button><div class="fn__space"></div><button class="b3-button b3-button--text">${window.siyuan.languages.confirm}</button></div>`,
                width: "360px",
                destroyCallback: () => resolve(chosen),
            });
            const select = dialog.element.querySelector("select");
            dialog.element.querySelector(".b3-button--cancel").addEventListener("click", () => dialog.destroy());
            dialog.element.querySelector(".b3-button--text").addEventListener("click", () => {
                chosen = select.value;
                this.settings.notebook = chosen;
                this.saveSettings();
                dialog.destroy();
            });
        });
    }
};
